(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-fp8-dit-attn"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-1\">一 · 一次线上事故：FP8 收益被 reduction kernel 吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-2\">二 · 它到底压缩了哪一段时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-3\">三 · 它不解决什么：softmax 与残差的数值敏感面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-4\">四 · 与 NVFP4 的分工：精度换吞吐的取舍线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-5\">五 · 规模上限：被 reduction 与 softmax 稳定性夹住</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-6\">六 · 边界在哪里：FP8 注意力救不了的那类单步时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-7\">七 · 边界：它救的是带宽与吞吐，不是数值鲁棒性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-8\">八 · 入口：BF16 latent 与 timestep embedding 的驻留代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-9\">九 · LayerNorm 输出到 QKV 投影：per-token 动态量化的 reduction 代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-10\">十 · Q·K^T 与 softmax·V：FP8 矩阵乘与 BF16 累加的混合路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-11\">十一 · FFN 两级 GEMM 与残差回写：反量化的位置决定精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-12\">十二 · 每 N 步校准与缓存复用：scale 漂移与长序列溢出</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-13\">十三 · 端到端代价账本：三段预算的分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-14\">十四 · 数据流视角下的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-15\">十五 · 边界条件：FP8 注意力与 GEMM 在什么情况下失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-16\">十六 · 量化公式的逐项解剖与误差下界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-17\">十七 · 从 roofline 推出单步时延的 max 形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-18\">十八 · 数据流伪代码：scale 的生命周期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-19\">十九 · 校准间隔与 scale 漂移的定量约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-20\">二十 · 精度配方与代价的联合取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-21\">二十一 · FP8 注意力与 GEMM 的失效边界与单步代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-22\">二十二 · 失效边界：softmax 与 reduction 的两处硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-23\">二十三 · 请求形态与批大小窗口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-24\">二十四 · 长度分布：序列维度的隐性约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-25\">二十五 · 并发结构与单步时延的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-26\">二十六 · 负载错配的三种典型崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-27\">二十七 · 与相邻精度档位的负载分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-28\">二十八 · 配方的可观测性与调参顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-29\">二十九 · 负载配方：FP8 收益只在特定请求形态下成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-30\">三十 · 硬件档位与算力预算的绑定方式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-31\">三十一 · 并行拓扑：单卡优先与张量并行的切分边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-32\">三十二 · 量化方案的组合与校准节奏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-33\">三十三 · KV 策略：QKV 缓存与中间激活缓存的容量换算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-34\">三十四 · 调度参数与可复现配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-35\">三十五 · 部署配方的失效边界：FP8 DiT 在什么条件下会反噬</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-36\">三十六 · 配方落地时的边界条件与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-37\">三十七 · 单步时延的两条腿：HBM 带宽与 FP8 张量核吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-38\">三十八 · 显存账本：权重、激活缓存与 QKV 中间态的三层占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-39\">三十九 · 通信面：张量并行下的 FP8 集合通信与 scale 同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-40\">四十 · 功耗与热：吞吐翻倍不等于每瓦吞吐翻倍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-41\">四十一 · 尾延迟：小 batch 的 reduction 开销与调度气泡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-42\">四十二 · 规模上去以后哪里先崩：四个依次触发的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-43\">四十三 · 规模上去以后，先崩的是 reduction 与 softmax 的数值余量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-44\">四十四 · 精度失败模式：从 FID 退化到注意力图崩坏</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-45\">四十五 · 显存与 OOM：激活缓存与 KV 的双重压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-46\">四十六 · 批抖动与 reduction 开销：小 batch 的收益陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-47\">四十七 · 路由不均与尾延迟尖刺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-48\">四十八 · 监控指标体系与回滚判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-49\">四十九 · FP8 注意力链路的失效边界与可回滚诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-50\">五十 · 对照轴：精度档位与实现复杂度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-51\">五十一 · 决策表：按负载形态选档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-52\">五十二 · 与 BF16 基线的分界条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-53\">五十三 · 与 NVFP4 混合精度的取舍边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-54\">五十四 · 与异步注意力及缓存类算法的耦合选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-55\">五十五 · 适用条件与规模上限的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-fp8-dit-attn-sec-56\">五十六 · 同族对照：BF16、FP8 与 NVFP4 之间的选型判据</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后，VAE latent 与 timestep embedding…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">LayerNorm 输出经动态 per-token scale 量化为 E…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">Q·K^T 与 softmax·V 在 FP8 Tensor Core 上…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">FFN 两级 GEMM 同样走 FP8，输出经反量化加回 BF16 残差</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">每 N 步校准一次 activation scale，写回 KV/中间缓存…</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-fp8-dit-attn-sec-1\">一 · 一次线上事故：FP8 收益被 reduction kernel 吃掉</h3>\n<p>某服务化 DiT 集群在把 QKV 投影与 FFN GEMM 从 BF16 切到 E4M3 后，离线基准显示单步时延下降，但上线后 P99 单图时延反而恶化。根因不在 Tensor Core，而在数据流的前端：LayerNorm 输出需要 per-token 动态 scale，这个 reduction kernel 在 batch=1 的请求形态下无法被批内其他请求摊薄，每次前向都要单独起一次 kernel，调度与同步开销直接落在关键路径上。更糟的是该 kernel 未与 CUDA Graph 融合，每步都要重放一次 host 侧 launch，单步时延被切成若干段短 kernel，Tensor Core 的 FP8 吞吐优势根本来不及体现。</p>\n<p>这个事故精确划出了本算法的适用边界：FP8 化解决的是<strong>GEMM 与注意力矩阵乘的吞吐与显存</strong>，不解决<strong>小 batch 下的 kernel 调度开销</strong>。用公式看，单步时延由两条路径的较大者决定：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>当 batch=1 时 $M_{\\text{attn}}$ 很小，第二项本应是瓶颈；但 per-token scale 的 reduction 是串行前置依赖，它把 $T_{\\text{step}}$ 的实际构成改写成“reduction + GEMM + 反量化”的加和，max 模型失效。工程判断很直接：FP8 的收益只有在 reduction 被 CUDA Graph 吸收、或 batch 大到足以让 reduction 相对 GEMM 可忽略时才兑现。批大小按显存与 SLO 取 1–8 的配方里，1–2 这一档必须默认开启图捕获，否则就是上面这起事故的复现。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-2\">二 · 它到底压缩了哪一段时延</h3>\n<p>Blackwell 上 DiT 的瓶颈结构是清楚的：QKV 投影、$Q\\cdot K^T$、$\\text{softmax}\\cdot V$、FFN 两级 GEMM 全部是矩阵乘，受 FP16 Tensor Core 吞吐与 HBM 带宽双重限制；同时权重与中间激活以 BF16 存放，显存占用高，直接压低了可用的 batch 与 latent 分辨率。FP8 化的目标是把这批算子统一搬到 E4M3，借原生 FP8 Tensor Core 约 2 倍的吞吐把计算项压下去，同时把权重与激活显存减半，让 KV（此处指 QKV 与中间激活缓存）容纳更大 batch 或更高分辨率 latent。</p>\n<p>量化本身是缩放截断：</p>\n<div class=\"formula\">$$x_q=\\text{clamp}\\left(\\text{round}\\left(\\frac{x}{s}\\right),-2^{m-1},2^{m-1}-1\\right),\\qquad s=\\frac{\\max|x|}{2^{m-1}}$$</div>\n<p>其中 $x$ 为激活、$s$ 为 per-token 动态 scale、$m$ 为 E4M3 尾数位宽。注意这个式子的代价结构：$s$ 依赖当前 token 的 $\\max|x|$，所以必须先算出整行的最大值才能量化，这就是 reduction 的来源，也是第一节事故的物理根源。它压缩的是 GEMM 的计算时间与显存带宽占用，压缩不了这次 reduction 的串行延迟。</p>\n<p>具体例子：一个 batch=4、latent 分辨率较高的请求，QKV 投影的 GEMM 在 BF16 下是单步时延主项；切到 FP8 后该项按吞吐比例缩短，权重显存减半使同一张卡能再塞下一个 batch，吞吐与显存同时受益。但如果把 batch 降到 1，GEMM 缩小到与 reduction 同量级，收益就被抵消——这正是适用边界的第一条：<strong>适合注意力与 FFN GEMM 占主导、显存受限的服务化部署</strong>，不适合极低 batch 且未做图捕获的时延敏感场景。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-3\">三 · 它不解决什么：softmax 与残差的数值敏感面</h3>\n<p>FP8 化把 QKV/FFN GEMM 与注意力矩阵乘降精度，但明确不碰两处：softmax 内部累加与残差通路。softmax 的指数运算对输入扰动极敏感，若在 FP8 域内累加，指数项的动态范围会直接溢出；残差是跨 block 的长程累加，量化误差会随层数累积。因此机制上规定 softmax 内部用 BF16 累加，残差与 LayerNorm 保留 BF16，只对进入 GEMM 的激活做 E4M3 量化。</p>\n<p>失败模式是可复现的：softmax 与残差未保留 BF16 累加时，FP8 量化误差沿注意力图累积，表现为 FID 明显退化与注意力图崩坏——不是均匀的画质下降，而是局部结构塌陷。另一条失败路径是 activation scale 校准间隔过长，scale 随输入分布漂移，长序列注意力出现数值溢出，输出 NaN 或色块。校准误差随样本数收缩：</p>\n<div class=\"formula\">$$\\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}}$$</div>\n<p>这说明每 N 步校准一次不是可选项而是稳定性约束：$N_{\\text{calib}}$ 太小则校准本身成为开销，太大则 $\\Delta_{\\text{err}}$ 抬头。工程上把校准写回 KV/中间缓存供后续 step 复用，是在“漂移”与“开销”之间取的一个固定节奏，长序列与高分辨率下必须保留更多 BF16 通道来兜住 outlier。</p>\n<p>因此本算法<strong>不解决</strong>：超长序列下的 softmax 数值稳定性、跨层残差误差累积、以及 outlier 通道的自动发现。这些要么靠保留 BF16 通道，要么靠相邻的混合精度方案处理，不在 FP8 统一降精度的能力范围内。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-4\">四 · 与 NVFP4 的分工：精度换吞吐的取舍线</h3>\n<p>同样是降精度，FP8 与 NVFP4 的分工是明确的：FP8 精度更高、实现更简单（E4M3 权重与激活、E5M2 承载梯度类敏感张量，per-tensor/per-channel scaling 即可），但吞吐只有 FP4 的一半。这意味着 FP8 的适用边界由画质敏感度与 kernel 调优资源共同决定：对画质更敏感、或团队没有足够资源把 FP4 的缩放与 outlier 处理调到稳定，就该停在 FP8；反过来，若显存与吞吐压力压倒画质容忍度，NVFP4 混合精度才是下一档。</p>\n<p>代价对比要落到具体项：FP8 把权重与激活显存减半，KV/中间激活缓存可容纳更大 batch 或更高分辨率 latent；NVFP4 进一步压缩显存但引入更复杂的缩放粒度与更高的数值风险。单步时延上，FP8 相对 BF16 基线降 30%–45%，这个区间的下限对应 reduction 开销未被完全摊薄的情形，上限对应 GEMM 占主导且图捕获到位的情形。工程判断：先用 FP8 拿到确定性的 2 倍 Tensor Core 吞吐与减半显存，把 reduction 与 CUDA Graph 的融合做扎实，再评估是否值得为 FP4 的额外吞吐承担数值调优成本。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>FP8（本算法）</th><th>NVFP4 混合精度</th></tr></thead><tbody><tr><td>Tensor Core 吞吐</td><td>约为 BF16 的 2 倍</td><td>约为 FP8 的 2 倍</td></tr><tr><td>数值风险</td><td>softmax/残差需 BF16 兜底</td><td>缩放粒度更细、outlier 处理更重</td></tr><tr><td>实现复杂度</td><td>per-token 动态 scale + 校准</td><td>更高，需专门 kernel 调优</td></tr><tr><td>适用信号</td><td>画质敏感、调优资源有限</td><td>显存与吞吐压力优先</td></tr></tbody></table>\n\n<h3 id=\"alg-fp8-dit-attn-sec-5\">五 · 规模上限：被 reduction 与 softmax 稳定性夹住</h3>\n<p>适用边界的第二条是规模上限。上限不由 Tensor Core 决定，而由两个软约束夹住：per-token 动态 scale 的 reduction 开销随 batch 减小而占比上升；softmax 数值稳定性随序列长度与分辨率上升而恶化。前者是吞吐侧的软上限，后者是精度侧的硬上限。</p>\n<p>把这两条写成工程判据：设单步中 GEMM 时间为 $T_{\\text{gemm}}$、reduction 时间为 $T_{\\text{red}}$，则 FP8 相对 BF16 的有效加速比近似为</p>\n<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{T_{\\text{gemm}}^{\\text{bf16}}}{T_{\\text{gemm}}^{\\text{fp8}} + T_{\\text{red}}}$$</div>\n<p>当 $T_{\\text{red}}$ 与 $T_{\\text{gemm}}^{\\text{fp8}}$ 同量级时，加速比被腰斩——这就是 batch=1 场景下 30%–45% 区间取下限甚至更差的机制解释。要抬上限，只有两条路：把 $T_{\\text{red}}$ 通过 CUDA Graph 与批内合并压到可忽略，或把 batch 抬到 $T_{\\text{gemm}}$ 远大于 $T_{\\text{red}}$。后者受显存约束，而 FP8 减半显存恰好松开了这个约束，形成正反馈：显存减半 → batch 可增大 → reduction 被摊薄 → 加速比上升。</p>\n<p>具体例子：同一张 Blackwell 卡，BF16 下 batch 只能取到较小值，reduction 占比高；切 FP8 后权重与激活显存减半，batch 上限抬升，reduction 相对 GEMM 的占比下降，单步时延的构成重新回到 max 模型主导。这解释了为什么本算法的收益高度依赖部署配方——并行拓扑以单卡为主、大模型走张量并行，量化配方固定为 E4M3 权重与激活、E5M2 敏感张量，任何一项偏离都会移动这条上限。</p>\n<p>最终落在一条具体机制上：FP8 化的收益兑现点不在 Tensor Core 峰值，而在 per-token scale 的 reduction 是否被图捕获吸收、以及 batch 是否被显存松绑抬到足以摊薄它。校准间隔、outlier 通道保留、softmax 的 BF16 累加，这三项是把精度侧硬上限往外推的必要条件；缺任何一项，规模上限就退回到“短序列、小分辨率、画质容忍度高”的窄区间。工程上判断一个 DiT 服务能否吃下 FP8，先看它的请求形态是 batch 1–8 中的哪一档、序列与分辨率是否触到 softmax 稳定性边界，再看 reduction 是否已进图——这三问的答案，比任何峰值吞吐数字都更能决定这套算法在该部署里是收益还是负债。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-6\">六 · 边界在哪里：FP8 注意力救不了的那类单步时延</h3>\n<p>把 QKV 投影、$Q\\cdot K^T$、$\\text{softmax}\\cdot V$ 与 FFN 两级 GEMM 统一降到 FP8，收益的前提是这些 GEMM 在单步时延里占主导。一旦主导项换成别的东西，这套方案就失效。典型事故形态是：某条 1024×1024 高分辨率 latent 的服务链路，在 batch=1、SLO 按单图时延计的配置下切到 FP8，GEMM 时间确实下来了，但端到端单步反而被拖慢——per-token 动态 scale 的 reduction kernel 在极小 batch 下无法被 GEMM 自身摊薄，kernel launch 与调度开销吃掉了 FP8 的收益。此时单步时延更接近</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right) + T_{\\text{reduce}}$$</div>\n<p>其中 $T_{\\text{reduce}}$ 是逐 token 求 $\\max|x|$ 再算 $s=\\max|x|/2^{m-1}$ 的规约代价，它不随 Tensor Core 吞吐下降而下降。这条链路的正确解法不是继续压 GEMM，而是把 reduction 与相邻算子融进 CUDA Graph、或改用更粗粒度的 per-channel scale 换取更少的规约次数；FP8 GEMM 本身在这里只是必要条件，不是充分条件。</p>\n<p>第二类失效来自数值而非调度。注意力 softmax 与残差对量化误差敏感：$Q\\cdot K^T$ 在 FP8 上执行后若 softmax 内部不保留 BF16 累加，指数项的舍入误差会沿序列维累积，注意力图出现整片塌陷，表现为色块与结构崩坏；残差路径若被一并降到 FP8，跨 block 的误差叠加会让 FID 明显退化。工程上的硬约束是：E4M3 承载权重与激活、E5M2 承载梯度类敏感张量，残差与 LayerNorm 必须留在 BF16，outlier 通道单独保留。这条约束不是调优选项，而是适用边界的一部分——凡是残差占比高、LayerNorm 后动态范围跨度大的 DiT 变体，FP8 的可用精度预算就更紧。</p>\n<p>第三类失效是校准漂移。activation scale 每 N 步校准一次并写回缓存供后续 step 复用，间隔过长时 scale 与实际激活分布脱节，长序列注意力在高动态范围 token 上溢出，输出 NaN。误差随校准样本量收缩的量级可写成 $\\Delta_{\\text{err}} \\approx \\Delta_{\\text{fp8}}/\\sqrt{N_{\\text{calib}}}$，这决定了校准频率不能只按 step 数拍脑袋，而要跟分辨率与序列长度挂钩。适用规模的上限也在这里：超长序列与高分辨率 latent 需要保留更多 BF16 通道，FP8 覆盖的算子比例随之下降，$\\text{FLOPs}_{\\text{eff}}=\\text{FLOPs}_{\\text{bf16}}/2$ 的理想账也就打折。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>FP8 是否为主收益来源</th><th>主要风险</th></tr></thead><tbody><tr><td>batch 1–8、GEMM 占主导、显存受限</td><td>是，单步时延可降 30%–45%</td><td>reduction 开销占比上升</td></tr><tr><td>超长序列 / 高分辨率 latent</td><td>部分，需保留更多 BF16 通道</td><td>softmax 溢出、scale 漂移</td></tr><tr><td>画质极敏感、kernel 调优资源有限</td><td>是，优于 NVFP4 混合精度</td><td>吞吐仅为 FP4 的一半</td></tr></tbody></table>\n<p>由此可以给出判断口径：这套方案解决的是 Blackwell 上 DiT 的 QKV/FFN GEMM 与注意力矩阵乘受 FP16 带宽与 Tensor Core 吞吐限制、权重与激活显存占用高、单步时延难压的问题，它不解决 VAE 解码、调度排队、跨卡通信这些不在 GEMM 里的时延项，也不解决精度预算本身不够的模型。选型上，对画质更敏感或 kernel 调优资源有限的团队应停在 FP8 而不是追 NVFP4；反之若 SLO 已被 GEMM 之外的环节卡住，先做算子融合与图捕获，再谈降精度。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-7\">七 · 边界：它救的是带宽与吞吐，不是数值鲁棒性</h3>\n<p>一次线上事故足以说明适用边界。某文生图服务在 B200 上把 DiT 的 QKV 与 FFN GEMM 整体切到 FP8，压测阶段单步时延下降明显，但上线后在高分辨率 latent、长序列注意力请求上开始出现色块与整图崩坏：softmax 输入动态范围被 per-tensor scale 压平，$Q\\cdot K^T$ 的极值被 clamp 到 E4M3 上限，注意力图退化为近似均匀分布，残差分支又把量化误差逐 step 累积。根因不是 FP8 格式本身，而是把「带宽与 Tensor Core 吞吐受限」这一诊断错误地外推成了「所有张量都该降精度」。这个算法真正解决的问题有明确形状：当 DiT 单步前向的时间被 QKV 投影、注意力矩阵乘与 FFN 两级 GEMM 主导，且权重与中间激活显存吃紧时，用 E4M3 承载权重与激活、E5M2 承载敏感张量、残差与 LayerNorm 保留 BF16，可以把算子搬到 Blackwell 原生 FP8 Tensor Core 上，换取约 2 倍的 Tensor Core 吞吐与减半的权重/激活显存。它不解决 softmax 数值稳定性、不解决 outlier 通道、不解决跨 step 的 scale 漂移——这些必须靠 BF16 累加、outlier 保留与周期性校准来兜底。</p>\n<p>失效条件可以写成一条可判定的边界。设校准样本数为 $N_{\\text{calib}}$，则 scale 误差随校准规模收缩：</p>\n<div class=\"formula\">$$\\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}},\\qquad T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>第一式说明校准间隔过长会让 activation scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块；第二式说明收益天花板：当注意力中间张量搬运 $M_{\\text{attn}}$ 仍受 HBM 带宽约束时，即使 FP8 Tensor Core 吞吐翻倍，单步时延也被带宽项钉住，此时继续压精度只增风险不增收益。典型反例是超长序列与高分辨率 latent：softmax 与残差需要保留更多 BF16 通道，FP8 覆盖比例下降，实测收益从 30%–45% 区间向带宽项收敛。</p>\n<p>系统代价还有一笔常被忽略的账：per-token 动态 scale 需要额外的 reduction kernel 求 $\\max|x|$ 再量化，批大小取 1–8 的服务化部署里，这个 kernel 的调度开销会吃掉相当比例的 FP8 收益，必须与 CUDA Graph 融合摊薄；未融合时小 batch 单图时延反而劣化。因此适用判断应落在三件事上：注意力与 FFN GEMM 是否占单步主导、显存是否构成 batch 或分辨率上限、以及是否有工程预算维护校准与 outlier 通道。相比 NVFP4 混合精度，FP8 精度更高、实现更简单但吞吐只有 FP4 的一半，适合对画质敏感或 kernel 调优资源有限的场景；若画质容忍度高且调优能力充足，边界应让给 FP4。</p>\n<h3 id=\"alg-fp8-dit-attn-sec-8\">八 · 入口：BF16 latent 与 timestep embedding 的驻留代价</h3>\n<p>请求进入 DiT 服务后，第一个落点是 latent 张量。VAE 编码产出的 latent 保持 BF16，形状为 <span class=\"inline\">[B, C, H, W]</span>，B 取 1–8，C 与分辨率按模型档位定。timestep embedding 同样以 BF16 注入每个 block 的调制分支（adaLN 的 scale/shift/gate）。这一步不做任何量化，原因在于 timestep embedding 是整条链路的条件信号源，一旦在此处引入 E4M3 舍入，误差会沿所有 block 的调制系数传播，且无法通过后续 per-token scale 补偿回来。</p>\n<p>代价落在显存与带宽两侧。以单步前向为单位，latent 与 timestep embedding 的读取量是固定的，与后续 GEMM 的算力需求无关，因此在小 batch 下这部分搬运会占据单步时间中不可压缩的一段。用公式刻画单步下界：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>入口段的搬运量计入 <span class=\"inline\">\\(M_{\\text{attn}}\\)</span> 的分子部分：latent 读一次、写一次，调制向量按 block 数重复读。当 B 取 1 时，<span class=\"inline\">FLOPs/TC_fp8</span> 项很小，<span class=\"inline\">\\(M_{\\text{attn}}/\\text{BW}_{\\text{HBM}}\\)</span> 成为主导项，此时入口 BF16 驻留就是单步时延的主要构成。工程判断是：入口张量不量化，但要把 latent 与调制向量的读取合并进同一个 CUDA Graph 节点，避免多次 kernel launch 之间的空转。</p>\n<p>具体例子：B=1、latent 分辨率较高时，单步前向的入口段只做一次 BF16 读入与一次调制广播，若这段被拆成三个独立 kernel（读 latent、算 embedding、广播到 block），launch 开销会直接吃掉 FP8 GEMM 省下的时间；合并后入口段退化为一次搬运，把预算留给后面的 QKV 投影。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-9\">九 · LayerNorm 输出到 QKV 投影：per-token 动态量化的 reduction 代价</h3>\n<p>LayerNorm 在 BF16 中完成，输出张量 <span class=\"inline\">X</span> 形状 <span class=\"inline\">[B, L, D]</span>（L 为 token 数，D 为隐藏维）。紧接着是量化步骤：对每个 token 行求 <span class=\"inline\">max|X|</span>，得到 per-token scale <span class=\"inline\">s</span>，再按缩放量化写入 E4M3：</p>\n<div class=\"formula\">$$x_q=\\text{clamp}\\left(\\text{round}\\left(\\frac{x}{s}\\right),-2^{m-1},2^{m-1}-1\\right),\\qquad s=\\frac{\\max|x|}{2^{m-1}}$$</div>\n<p>这里 <span class=\"inline\">m</span> 是 E4M3 的尾数位宽，clamp 的上下界由格式的表示范围决定。per-token 而非 per-tensor 的理由是 DiT 激活在不同 token 上的动态范围差异大，per-tensor 会把小值 token 整体压进低位，注意力图出现块状失真。per-token 的代价是一个 reduction kernel：沿 D 维求最大值，再逐元素除、round、clamp、写回。这个 kernel 的访存量约为 <span class=\"inline\">\\(2 \\times B \\times L \\times D \\times 2\\)</span> 字节（读 BF16、写 FP8 各一遍），在 B=1、L 较大时与 QKV GEMM 本身的读权重带宽同量级。</p>\n<p>QKV 投影随后在 FP8 Tensor Core 上执行，权重为 E4M3（离线 per-channel 量化），激活为刚写入的 E4M3，累加在 FP32。Blackwell 的 FP8 吞吐约为 BF16 的 2 倍，因此这一步的算力项直接减半，有效 FLOPs 记为：</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{eff}} = \\frac{\\text{FLOPs}_{\\text{bf16}}}{2}$$</div>\n<p>系统代价的分配在小 batch 下发生反转：B=1 时 reduction kernel 的固定开销占比上升，因为 GEMM 的算力项随 B 线性缩小而 reduction 的 launch 与同步开销不缩。失败模式很明确——per-token scale 的 reduction 未与 CUDA Graph 融合，小 batch 下调度开销吃掉 FP8 收益。工程做法是把 max-reduce、量化、GEMM 的 prologue 融进同一张图，让 reduction 的输出直接作为 GEMM 的 A 操作数驻留片上，避免一次 HBM 往返。</p>\n<p>具体例子：一个 block 内 QKV 投影的输入是 LayerNorm 后的 <span class=\"inline\">[B, L, D]</span>，若量化 kernel 单独 launch，则每次前向多出一次全张量读写；融合进 CUDA Graph 后，reduction 与 GEMM 的 tile 加载共享同一段流水，B=1 场景下这条链路的时延贡献从“两次搬运加一次算力”压缩为“一次搬运加一次算力”。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-10\">十 · Q·K^T 与 softmax·V：FP8 矩阵乘与 BF16 累加的混合路径</h3>\n<p>QKV 投影输出三个 FP8 张量，进入注意力。第一步是 <span class=\"inline\">\\(Q \\cdot K^T\\)</span>，两个操作数均为 E4M3，Tensor Core 以 FP8 模式执行乘加，累加器为 FP32。得到 logits 后转 BF16 做 softmax：减行最大值、指数、归一化。softmax 内部必须保留 BF16（乃至 FP32）累加，理由是 E4M3 的动态范围窄，指数运算后的中间值若继续以 FP8 承载会直接溢出或下溢，注意力图崩坏。</p>\n<p>第二步是 <span class=\"inline\">\\(\\text{softmax} \\cdot V\\)</span>，softmax 结果需重新量化为 E4M3 才能喂给 FP8 Tensor Core，V 保持 E4M3。这一步的量化是整条链路中最敏感的一处：softmax 输出分布在 [0,1] 且大量元素接近 0，per-tensor scale 会把有效位浪费在极小值上，通常改用 per-row（按 query 行）scale，并对 outlier 通道保留 BF16 旁路。</p>\n<p>代价分析：注意力的 <span class=\"inline\">\\(Q \\cdot K^T\\)</span> 计算量为 <span class=\"inline\">\\(O(B \\cdot H \\cdot L^2 \\cdot d)\\)</span>，在 L 较大时是单步 FLOPs 的主要来源，FP8 化后算力项减半；但 softmax 的 BF16 段落是纯访存与特殊函数运算，不享受 Tensor Core 加速，成为 Amdahl 意义上的串行段。用 <span class=\"inline\">\\(T_{\\text{step}}\\)</span> 公式看，当 L 增大，<span class=\"inline\">\\(M_{\\text{attn}}\\)</span> 中的 logits 读写量以 <span class=\"inline\">L^2</span> 增长，BF16 softmax 的搬运可能反超 FP8 GEMM 的算力项，此时单步时延由带宽而非算力决定。</p>\n<p>具体例子：L 较大、B=1 时，<span class=\"inline\">\\(Q \\cdot K^T\\)</span> 的 FP8 GEMM 很快完成，但 logits 写回 HBM 再读入 softmax 的往返成为瓶颈；工程上把 softmax 融进注意力的 epilogue，logits 停留在片上 SRAM，只把归一化后的 E4M3 结果写回，省掉一次 <span class=\"inline\">L^2</span> 量级的 HBM 往返。这正是 Blackwell 异步注意力路径要解决的问题，此处只指路，不展开。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-11\">十一 · FFN 两级 GEMM 与残差回写：反量化的位置决定精度</h3>\n<p>注意力输出经输出投影（同样 FP8）后，进入 FFN。FFN 是两级 GEMM：第一级升维到中间维（通常为 4D 或按模型定的倍率），第二级降回 D。两级均以 E4M3 权重与 E4M3 激活执行，中间激活在第一级输出后需重新量化——第一级 GEMM 的 FP32 累加结果先反量化到 BF16，过激活函数（GELU/SwiGLU），再按 per-token scale 量化为 E4M3 喂第二级。</p>\n<p>关键判断在反量化的位置。若在第一级 GEMM 的 epilogue 直接以 FP8 输出而不回 BF16，激活函数的非线性会把量化误差放大；若回 BF16 再过非线性再量化，则多一次 BF16 往返但精度可控。工程上选后者，代价是 FFN 段多一次 <span class=\"inline\">\\(B \\times L \\times 4D\\)</span> 的 BF16 读写，在 B=1 时这段搬运与两级 GEMM 的算力项可比。</p>\n<p>残差与 LayerNorm 全程保留 BF16。FFN 第二级 GEMM 的输出反量化后加回 BF16 残差，得到 block 输出。残差保留 BF16 的理由是跨 block 的累加：若残差也降为 FP8，误差会随 block 深度线性累积，最终 FID 明显退化。这一步的代价是残差张量始终以 BF16 驻留，显存减半的收益在残差上不成立——权重与激活减半，但残差缓冲仍是 BF16，这是 FP8 方案显存账本里必须单独列出的一项。</p>\n<p>具体例子：一个 DiT block 的 FFN 中间维为 4D，第一级 GEMM 输出 <span class=\"inline\">[B, L, 4D]</span> 的 FP32 累加，反量化到 BF16 后过 SwiGLU，再量化回 E4M3；若把这步的 BF16 往返省掉，中间激活的量化误差经第二级 GEMM 放大后进入残差，单步输出出现可见色偏。系统代价上，这次往返的带宽开销在小 batch 下是 FFN 段的主要非算力成本。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-12\">十二 · 每 N 步校准与缓存复用：scale 漂移与长序列溢出</h3>\n<p>activation scale 不是一次性离线确定的。扩散采样过程中，不同 step 的激活分布随噪声水平变化，固定 scale 会在某些 step 上过紧（截断）或过松（浪费位宽）。机制是每 N 步校准一次：取当前 step 的激活统计，更新 per-token 或 per-channel scale，写回 KV/中间缓存供后续 step 复用。校准的输入是若干 token 的 <span class=\"inline\">max|x|</span> 统计，输出是更新后的 scale 表；代价是一次额外的统计 kernel 与一次缓存写回，摊销到 N 个 step 上。</p>\n<p>校准间隔的选择直接对应失败模式。间隔过长，activation scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块；间隔过短，校准 kernel 的固定开销在单步时延中占比上升，尤其 B=1 时。校准误差与样本数的关系可定性写成：</p>\n<div class=\"formula\">$$\\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}}$$</div>\n<p>其中 <span class=\"inline\">\\(N_{\\text{calib}}\\)</span> 是参与统计的 token 数，<span class=\"inline\">\\(\\Delta_{\\text{fp8}}\\)</span> 是单次量化的固有误差。这个式子说明校准样本越多误差越小，但统计 kernel 的访存量随 <span class=\"inline\">\\(N_{\\text{calib}}\\)</span> 线性增长，存在明确的性价比拐点。</p>\n<p>缓存复用的边界要划清：KV 指 QKV 与中间激活缓存，不是自回归解码的 KV cache。跨 step 复用 scale 表能省掉重复统计，但复用的是 scale 而非激活本身——扩散每步的 latent 不同，激活必须重算。工程判断是：把 scale 表作为持久化的小张量驻留显存，校准 kernel 只在第 <span class=\"inline\">kN</span> 步触发，其余 step 直接读表，用 CUDA Graph 把“读表—量化—GEMM”固化成一条固定拓扑。</p>\n<p>具体例子：长序列注意力场景下，若 N 取过大，某一步的激活峰值超出旧 scale 的表示范围，E4M3 的 clamp 把大值截断，注意力 logits 出现平坦化，采样结果表现为局部色块；把 N 收紧并在校准中保留 outlier 通道的 BF16 旁路后，溢出消失，代价是每 N 步多一次统计 kernel 的 launch，需与图融合摊薄。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-13\">十三 · 端到端代价账本：三段预算的分配</h3>\n<p>把上述步骤按数据流串起来，单步时延可拆为三段：入口 BF16 搬运、GEMM 算力（QKV/注意力/FFN，FP8）、softmax 与反量化的 BF16 串行段。三段的比例随 B 与 L 变化。B 小、L 大时，入口与 softmax 段占比上升，FP8 的算力收益被带宽与串行段稀释；B 增大时，GEMM 算力项线性增长，FP8 的 2 倍吞吐收益充分释放，单步时延降幅向 30%–45% 靠拢。</p>\n<p>显存账本同样分三段：权重与激活减半（E4M3 相对 BF16），残差与 LayerNorm 缓冲保持 BF16 不减半，scale 表与校准缓存是新增的小额开销。净收益是权重与激活显存减半后可容纳更大 batch 或更高分辨率 latent，但残差缓冲的 BF16 占用是硬下限，不能按“整体减半”估算容量。</p>\n<p>工程判断落在预算分配上：若 SLO 以单图时延计且 B 取小值，优化重点应放在 reduction kernel 与 softmax 的融合上，而非继续压 GEMM 精度；若 B 取大值、吞吐导向，则 FP8 GEMM 的算力收益是主项，此时要保证 per-token scale 的 reduction 不成为新的串行瓶颈。三段预算的边界由 <span class=\"inline\">\\(T_{\\text{step}}\\)</span> 公式中的 max 项决定——哪一项大，优化就投向哪一项，而不是笼统地把所有算子搬到 FP8。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-14\">十四 · 数据流视角下的失效边界与系统代价</h3>\n<p>把 FP8 方案按 token 流动顺序摊开看，代价并不均匀。第一段是 LayerNorm 到 QKV：输入 BF16 激活，输出 E4M3 张量与 per-token scale。这里的核心机制是 $x_q=\\text{clamp}(\\text{round}(x/s),-2^{m-1},2^{m-1}-1)$，$s=\\max|x|/2^{m-1}$，每个 token 一次 reduction 求 $\\max|x|$。代价是额外一个 reduction kernel 与一次全量读写：激活显存减半省下的带宽，被这次 reduction 部分吃掉。小 batch（1–8）时 reduction 的固定调度开销占比上升，若不与 CUDA Graph 融合，单步时延的收益会被摊薄，这是该方案最先失效的地方。</p>\n<p>第二段是 $Q\\cdot K^T$ 与 $\\text{softmax}\\cdot V$。输入 E4M3 的 Q/K/V，输出 BF16 累加的注意力结果。FP8 Tensor Core 吞吐约为 BF16 的 2 倍，但 softmax 内部必须保留 BF16 累加，否则指数项在 E4M3 的动态范围下溢出，注意力图崩坏、FID 明显退化。失效条件是 outlier 通道未被单独保留：少数通道的 $\\max|x|$ 远高于其余通道，per-token scale 被拉大，其余通道的有效尾数位被压缩，量化噪声进入 softmax 分母。长序列下这一效应放大，若校准间隔过长，activation scale 漂移，数值溢出表现为 NaN 或色块。</p>\n<p>第三段是 FFN 两级 GEMM 与残差回写。输入 E4M3 激活与权重，输出经反量化的 BF16 增量加回残差。残差与 LayerNorm 保留 BF16 是硬约束，不是可选优化。此段的系统代价可用 $T_{\\text{step}} \\approx \\max(M_{\\text{attn}}/\\text{BW}_{\\text{HBM}}, \\text{FLOPs}/\\text{TC}_{\\text{fp8}})$ 判断：显存受限时受带宽项支配，算力受限时受 FP8 吞吐项支配，FP8 只改善后者，前者要靠权重与激活显存减半后容纳更大 batch 或更高分辨率 latent 来摊薄。规模上限因此由 softmax 数值稳定性与 reduction 开销共同约束，超长序列与高分辨率下需保留更多 BF16 通道，等于把部分收益退回。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>输入/输出</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>LN→QKV</td><td>BF16→E4M3+scale</td><td>reduction kernel、调度开销</td><td>小 batch 未融合 CUDA Graph</td></tr><tr><td>QK^T/softmax·V</td><td>E4M3→BF16 累加</td><td>outlier 通道保留</td><td>scale 漂移、长序列溢出</td></tr><tr><td>FFN+残差</td><td>E4M3→BF16 回写</td><td>反量化、残差带宽</td><td>残差未保 BF16</td></tr></tbody></table>\n\n<h3 id=\"alg-fp8-dit-attn-sec-15\">十五 · 边界条件：FP8 注意力与 GEMM 在什么情况下失效</h3>\n<p>FP8 路线的收益并非无条件成立。把 QKV 投影、$Q\\cdot K^T$、$\\text{softmax}\\cdot V$ 与 FFN 两级 GEMM 统一降到 E4M3 后，单步时延由 HBM 搬运与 Tensor Core 计算中较慢的一项决定：<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>当 batch 取 1–8、latent 分辨率不高时，$M_{\\text{attn}}$ 很小而 GEMM 的 FLOPs 占主导，FP8 把 $\\text{TC}_{\\text{fp8}}$ 抬到 BF16 的两倍，$T_{\\text{step}}$ 落到计算项上，收益才兑现；反之若序列拉长、注意力矩阵规模膨胀，搬运项压过计算项，FP8 对时延的贡献被稀释，此时真正的瓶颈是 KV 与中间激活的读写带宽，而非 Tensor Core 吞吐。</p>\n<p>数值侧的失效条件更硬。softmax 内部必须保留 BF16 累加，残差与 LayerNorm 也必须留在 BF16，否则量化误差沿 block 逐层累积，注意力图出现崩坏、FID 明显退化。per-token 动态 scale 的 reduction kernel 是小 batch 下的隐性代价：批越小，这个 kernel 的固定调度开销占比越高，若未与 CUDA Graph 融合，吃掉的可观时延足以抵消 FP8 收益。校准间隔同样构成边界——间隔过长会让 activation scale 随 timestep 漂移，长序列注意力出现数值溢出，输出 NaN 或色块；校准误差随样本数收敛为 $\\Delta_{\\text{err}} \\approx \\Delta_{\\text{fp8}}/\\sqrt{N_{\\text{calib}}}$，意味着缩短间隔或增大校准集是压制漂移的直接手段，但前者增加每 N 步的额外前向开销。</p>\n<p>工程判断上，这套方案适合注意力与 FFN GEMM 占主导、显存受限的服务化部署：权重与激活显存减半后可容纳更大 batch 或更高分辨率 latent，而单步时延降 30%–45% 的前提是 reduction 开销被 CUDA Graph 摊薄、outlier 通道被显式保留。相对 NVFP4 混合精度，FP8 精度更高、实现更简单，但吞吐只有 FP4 的一半——对画质敏感或 kernel 调优资源有限的场景选 FP8，追求极限吞吐且能承受更复杂离群值处理时才考虑 FP4。超长序列与高分辨率下需保留更多 BF16 通道，规模上限正被 softmax 数值稳定性与 reduction 开销这两条约束卡住。</p>\n<h3 id=\"alg-fp8-dit-attn-sec-16\">十六 · 量化公式的逐项解剖与误差下界</h3>\n<p>把 DiT 的 QKV 投影搬到 FP8，第一步不是写 kernel，而是把量化式写成可推导的形式。核心式是 <span class=\"formula\">$$x_q=\\text{clamp}\\left(\\text{round}\\left(\\frac{x}{s}\\right),-2^{m-1},2^{m-1}-1\\right),\\qquad s=\\frac{\\max|x|}{2^{m-1}}$$</span> 三项各自对应一个工程决策：<em>round</em> 决定舍入误差的分布，<em>clamp</em> 决定饱和截断的边界，<em>s</em> 决定动态范围如何映射到 E4M3 的尾数位宽 <em>m</em>。E4M3 的指数位只有 4 位，可表示范围窄，因此 <em>s</em> 取 per-token 最大值而非全局最大值，是把动态范围压缩到单个 token 的激活分布上——这正是 LayerNorm 输出后立刻量化的理由：LayerNorm 已经把每个 token 的均值方差归一，per-token 的 <em>max|x|</em> 才是稳定可估的量。</p>\n<p>推导的关键一步在误差项。设真实激活 <em>x</em>，量化后 <em>x_q·s</em>，单次舍入误差上界为 <em>s/2</em>，而 <em>s = max|x|/2^{m-1}</em>，于是相对误差被 <em>max|x|</em> 归一化后正比于 <em>2^{-m}</em>。当一层内有 <em>N</em> 个独立量化项参与同一次累加（例如 K 维点积），误差按独立同分布叠加，标准差按 <em>√N</em> 增长而信号按 <em>N</em> 增长，因此相对误差收缩为 <span class=\"formula\">$$\\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}}$$</span> 这里的 <em>N_calib</em> 不是序列长度，而是参与校准统计的样本数——它决定了 scale 估计本身的置信度。这条式子给出两个可执行判断：其一，K 维越大，FP8 点积的相对误差越小，因此 QKV 投影这类 K 很大的 GEMM 天生比小矩阵乘更耐受 FP8；其二，校准样本不足时 <em>Δ_err</em> 不收敛，activation scale 会漂移，这正是长序列注意力出现数值溢出的根源，而不是 softmax 本身的问题。</p>\n<p>代价侧要对齐：E4M3 权重与激活使显存减半，QKV 与中间激活缓存可容纳更大 batch 或更高分辨率 latent；但 per-token 动态 scale 需要一次跨 K 维的 reduction 才能拿到 <em>max|x|</em>，这个 kernel 在小 batch 下无法被 GEMM 的算力掩盖。工程上的判据是 reduction 时间与 GEMM 时间的比值：batch 取 1–8 时，reduction 占比上升，必须与 CUDA Graph 融合以摊薄调度成本，否则 FP8 的吞吐收益被吃掉。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-17\">十七 · 从 roofline 推出单步时延的 max 形式</h3>\n<p>单步时延的公式写成两个下界的最大值：<span class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</span> 第一项是注意力中间矩阵的搬运时间，<em>M_attn</em> 是 Q·K^T 与 softmax·V 需要落盘或跨层传递的字节量；第二项是 Tensor Core 的计算时间，<em>TC_fp8</em> 在 Blackwell 上约为 BF16 的 2 倍。这个 max 形式本身就是推导结论：当序列短、batch 小，<em>M_attn</em> 小，时延被计算项支配，FP8 直接兑现 2 倍吞吐；当分辨率抬高、latent token 数上升，<em>M_attn</em> 随 token 数平方增长，搬运项反过来支配，此时降精度只减半字节宽度，收益被带宽上限截断。</p>\n<p>关键推导一步是把 <em>M_attn</em> 拆成“写 + 读”两段：注意力矩阵在 FP8 下每元素 1 字节，但 softmax 内部必须 BF16 累加，意味着中间结果在寄存器或 shared memory 中以 BF16 存在，只有跨 kernel 边界的部分才以 FP8 落 HBM。因此 <em>M_attn</em> 的有效字节数不是简单的 <em>token²×1</em>，而是被分块策略决定的分块边界流量。这解释了为什么 Blackwell 上的异步注意力路径（见本套书注意力分册）与本节的 FP8 化必须联合调：分块越大，跨边界流量越小，max 形式越偏向计算项，FP8 的 2 倍吞吐才真正可见。</p>\n<p>具体例子：一个以 QKV/FFN GEMM 占主导的 DiT 单步前向，batch 取 4，latent 分辨率中等。BF16 下计算项主导，单步时延受 Tensor Core 吞吐限制；切到 FP8 后 <em>TC_fp8</em> 翻倍，计算项减半，但 reduction kernel 与反量化加残差的额外访存进入 <em>M_attn</em> 一侧，实测收益落在 30%–45% 区间而非理论 50%——差额正是搬运项与 reduction 开销。这不是调优不足，而是 max 形式的必然：只要有一项没同步减半，总时延就不会线性跟随。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-18\">十八 · 数据流伪代码：scale 的生命周期</h3>\n<p>把机制落到可实现，伪代码要显式写出 scale 的产生、消费与回收三个时刻，而不是把量化藏进 GEMM 调用里。</p>\n<ul>\n<li>入口：latent 与 timestep embedding 以 BF16 进入 block，残差副本保留 BF16 不动。</li>\n<li>LayerNorm 后：对每个 token 沿 K 维求 <em>max|x|</em>，得 per-token <em>s</em>，量化为 E4M3 写入 QKV 投影输入缓冲；<em>s</em> 本身以 FP32 存一张长度等于 token 数的小表。</li>\n<li>QKV GEMM：权重侧用 per-channel scale（离线校准得到），激活侧用 per-token scale，两者在 epilogue 中合并为一次反量化乘子，避免逐元素除法。</li>\n<li>注意力：Q·K^T 在 FP8 Tensor Core 上执行，累加器 BF16；softmax 全程 BF16，输出再量化回 E4M3 供 softmax·V 使用；此处必须保留 outlier 通道，否则注意力图崩坏。</li>\n<li>FFN：两级 GEMM 同样 FP8，第二级输出反量化后加回 BF16 残差。</li>\n<li>校准：每 N 步用当前 batch 的激活统计刷新 activation scale，写回缓存供后续 step 复用。</li>\n</ul>\n<p>伪代码层面的两个易错点值得单独指出。第一，per-token scale 的 reduction 必须与后续 GEMM 在同一 CUDA Graph 捕获内，否则小 batch 下 kernel launch 与同步开销直接吃掉 FP8 收益；第二，反量化乘子应在 epilogue 里以向量化方式施加，而不是先写回 BF16 缓冲再读出来做逐元素乘，后者会把显存流量翻倍，直接推高 <em>M_attn</em> 项。E5M2 只用于梯度类敏感张量，推理路径上不应出现在 QKV/FFN 的主数据流中——它的动态范围大但尾数少，用在激活上会放大 <em>Δ_err</em>。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-19\">十九 · 校准间隔与 scale 漂移的定量约束</h3>\n<p>校准间隔 <em>N</em> 不是拍脑袋的超参，它由 <em>Δ_err</em> 式约束。设第 <em>k</em> 步的真实激活分布相对校准时刻的偏移为 <em>δ_k</em>，则有效 scale 偏差使相对误差从 <em>Δ_fp8/√N_calib</em> 抬升到 <em>(Δ_fp8+δ_k)/√N_calib</em>。漂移 <em>δ_k</em> 随扩散步数累积，因为 DiT 的激活统计随 timestep 变化——早期步高噪声、晚期步细节丰富，同一张 scale 表跨全程使用必然失配。工程判据是：当 <em>δ_k</em> 与 <em>Δ_fp8</em> 同量级时，误差翻倍，此时必须刷新 scale。</p>\n<p>代价是刷新本身要一次前向统计，若每步都刷，reduction 开销回到小 batch 的痛点；若间隔过长，长序列注意力出现数值溢出，输出 NaN 或色块。折中做法是把校准绑定到阶段边界而非固定步数：在 timestep 跨越噪声等级切换点时刷新，其余步复用缓存。这与本套书阶段级扩散服务流水的切分点天然对齐，scale 表可以随阶段一起预热。</p>\n<p>具体例子：高分辨率 latent 下 token 数上升，注意力矩阵的 <em>max|x|</em> 分布尾部变厚，per-token scale 若仍按旧统计取值，clamp 会截断尾部激活，softmax 输入出现系统性偏移，注意力图在若干步后崩坏。此时保留 BF16 累加只能防溢出，防不住截断——必须在分辨率切换时强制刷新 scale，并把 outlier 通道以 BF16 旁路送出。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-20\">二十 · 精度配方与代价的联合取舍</h3>\n<p>配方层面：E4M3 承载权重与激活，E5M2 承载梯度类敏感张量，残差与 LayerNorm 保留 BF16。这个组合不是精度越高越好，而是按张量在数据流中的位置分配位宽。残差通路上任何量化误差都会被后续所有 block 累加放大，因此必须 BF16；LayerNorm 的均值方差统计对量化极敏感，也必须 BF16；而 QKV/FFN 的 GEMM 输入输出处于归一化之后、残差相加之前，误差被单层吸收，才适合 FP8。</p>\n<p>与相邻算法的取舍要写清楚：相比 BF16 基线，FP8 把 QKV/FFN GEMM 与注意力矩阵乘统一降精度，单步时延降 30%–45%，权重与激活显存减半；相比 NVFP4 混合精度（见本套书对应条目），FP8 精度更高、实现更简单，不需要复杂的块级 scale 与残差补偿，但吞吐只有 FP4 的一半。因此 FP8 的适用边界是：注意力与 FFN GEMM 占主导、显存受限、且对画质敏感或 kernel 调优资源有限的服务化部署。规模上限受 softmax 数值稳定性与 reduction 开销双重约束，超长序列与高分辨率下必须保留更多 BF16 通道，此时 FP8 的吞吐优势被 <em>M_attn</em> 项稀释。</p>\n<p>工程判断落在一条可测的线上：把 reduction kernel 与反量化 epilogue 的耗时单独打点，若两者之和超过 GEMM 时间的某个比例，就说明当前 batch 与分辨率下 FP8 的净收益已被搬运项吃掉，应回退到 BF16 或改用分块更粗的注意力路径，而不是继续加大量化激进度。这条线比任何理论吞吐数字都更能决定一次部署是否该上 FP8。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-21\">二十一 · FP8 注意力与 GEMM 的失效边界与单步代价账</h3>\n<p>把 QKV/FFN GEMM 与 $Q\\cdot K^T$、$\\text{softmax}\\cdot V$ 统一降到 FP8，收益不是无条件的。量化本身写成 $x_q=\\text{clamp}(\\text{round}(x/s),-2^{m-1},2^{m-1}-1)$、$s=\\max|x|/2^{m-1}$，其中 $s$ 是 per-token 动态 scale、$m$ 为 E4M3 尾数位宽；关键一步在于 $s$ 由当前 token 的激活最大值现算，因此 scale 的准确度直接决定 $\\Delta_{\\text{err}}\\approx \\Delta_{\\text{fp8}}/\\sqrt{N_{\\text{calib}}}$ 能否被校准样本数摊薄。失效条件有三类：softmax 与残差若不留 BF16 累加与 outlier 通道，量化误差沿 timestep 累积，表现为 FID 退化与注意力图崩坏；per-token reduction kernel 未与 CUDA Graph 融合时，小 batch（1–8）下调度开销吃掉 FP8 收益；校准间隔过长使 activation scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块。</p>\n<p>单步时延的账要按 $T_{\\text{step}}\\approx\\max(M_{\\text{attn}}/\\text{BW}_{\\text{HBM}},\\text{FLOPs}/\\text{TC}_{\\text{fp8}})$ 拆开看：FP8 把 $\\text{FLOPs}_{\\text{eff}}$ 压到 BF16 的一半、Tensor Core 吞吐约为 BF16 的 2 倍，计算项受益明显；但 $M_{\\text{attn}}$ 项受 HBM 带宽约束，权重与激活显存减半只缓解容量、不改变单位字节搬运时间，因此高分辨率 latent 与超长序列下瓶颈会从 Tensor Core 滑向带宽与 reduction。工程判断是：当注意力与 FFN GEMM 占主导、显存受限时上 FP8；当序列极长、softmax 数值窗口变窄时，保留更多 BF16 通道比强行全 FP8 更稳。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th><th>缓解</th></tr></thead><tbody><tr><td>softmax/残差误差累积</td><td>无 BF16 累加、无 outlier 通道</td><td>FID 退化、注意力图崩坏</td><td>softmax 内 BF16 累加，残差与 LayerNorm 留 BF16</td></tr><tr><td>reduction 调度开销</td><td>batch 1–8、未融合 CUDA Graph</td><td>单步时延收益被吃掉</td><td>scale kernel 与图融合，摊薄调度</td></tr><tr><td>scale 漂移溢出</td><td>校准间隔过长、长序列</td><td>NaN/色块，重跑浪费算力</td><td>每 N 步校准并写回缓存</td></tr></tbody></table>\n<p>伪代码落到可实现层面，核心是把量化点钉在 LayerNorm 之后、GEMM 之前，反量化点钉在 GEMM 之后、残差相加之前：对每个 token 求 $s$，量化写 E4M3 进 QKV 投影；$Q\\cdot K^T$ 与 $\\text{softmax}\\cdot V$ 在 FP8 Tensor Core 上跑，softmax 内部用 BF16 累加防溢出；FFN 两级 GEMM 同走 FP8，输出反量化加回 BF16 残差；每 N 步校准一次 activation scale 写回 KV/中间缓存供后续 step 复用。相比 NVFP4 混合精度，FP8 精度更高、实现更简单，但吞吐只有 FP4 的一半，适合画质敏感或 kernel 调优资源有限的场景；相比 BF16 基线，单步时延可降 30%–45%，代价是必须为 reduction 与校准留出工程预算。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-22\">二十二 · 失效边界：softmax 与 reduction 的两处硬约束</h3>\n<p>FP8 收益并非无条件成立，两条边界决定了它能否落地。第一条在注意力内部：$Q\\cdot K^T$ 的 FP8 结果进入 softmax 前必须先转 BF16 累加，因为 E4M3 的指数位仅 4 位、动态范围窄，logits 经 per-token scale 后若直接以 FP8 参与 exp 与归一化，长序列下 max 值偏移会把尾部概率压成零，注意力图出现结构性崩坏，FID 退化不可逆。第二条在量化前端：per-token 动态 scale 需要一次跨通道 reduction 求 $\\max|x|$，该 kernel 的启动与同步开销在 batch=1–8 时无法被 GEMM 主循环掩盖，若未与 CUDA Graph 融合，单步时延反被吃掉。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\underbrace{\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}}_{\\text{权重/激活搬运}} + \\underbrace{\\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}}_{\\text{GEMM}} + \\underbrace{t_{\\text{red}}(N_{\\text{tok}})}_{\\text{scale reduction}}$$</div>\n<p>上式把单步时延拆成三段：前两项由 Blackwell 的 HBM 带宽与 FP8 Tensor Core 吞吐决定，第三项是纯增量代价。当 $N_{\\text{tok}}$ 小、GEMM 本身已接近带宽上限时，$t_{\\text{red}}$ 占比上升，FP8 相对 BF16 的 2 倍吞吐优势被部分抵消——这正是小 batch 服务化场景必须先做 CUDA Graph 捕获的原因。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发场景</th><th>系统代价</th></tr></thead><tbody><tr><td>softmax 未保留 BF16 累加</td><td>长序列、高分辨率 latent</td><td>注意力图崩坏、FID 退化</td></tr><tr><td>reduction 未融合</td><td>batch 1–8 小批量</td><td>调度开销侵蚀时延收益</td></tr><tr><td>校准间隔过长</td><td>activation scale 漂移</td><td>数值溢出、输出 NaN 或色块</td></tr></tbody></table>\n<p>校准间隔是第三条隐性边界：每 N 步写回 activation scale 的机制假设分布漂移缓慢，一旦 N 过大，扩散采样后期的激活幅值超出旧 scale 覆盖范围，E4M3 饱和截断直接表现为色块。工程判断是：把 softmax 的 BF16 累加与 outlier 通道作为不可协商的保留项，把 reduction 融合进 CUDA Graph 作为性能前提，二者任一缺失，FP8 的 30%–45% 单步时延收益就不足以补偿画质与稳定性损失。</p>\n<h3 id=\"alg-fp8-dit-attn-sec-23\">二十三 · 请求形态与批大小窗口</h3>\n<p>FP8 注意力的收益不是无条件成立的，它绑定在一组特定的请求形态上。该算法服务的对象是 DiT 单步前向的批量 latent 生成：一次请求对应一个（或一组）latent，经过若干去噪步后由 VAE 解码。批大小按显存与 SLO 取 1–8，SLO 以单图时延计。这个窗口窄得有些反直觉——它不是“越大越好”，而是被两个方向同时挤压。</p>\n<p>向上挤压来自 softmax 与残差的数值稳定性。注意力 softmax 与残差对量化误差敏感，需保留 BF16 累加与 outlier 通道，否则 FID 明显退化。批越大，outlier 通道在 per-token scale 下的分布越难被单一缩放因子覆盖，误差沿残差路径累积的步数也越多。向下挤压来自 per-token 动态 scale 的 reduction kernel：它要为每个 token 求 $\\max|x|$ 再算 $s=\\max|x|/2^{m-1}$，这个 kernel 的固定开销在小 batch 下无法被 GEMM 摊薄，直接吃掉 FP8 的时延收益。批大小 1–8 正是这两条曲线交点附近的区间。</p>\n<p>判断负载是否落在配方内的第一个信号是单步时延的批缩放曲线。若 batch 从 1 增到 4 时单步时延几乎不涨，说明 GEMM 仍在吞吐受限区，配方成立；若 batch=1 时 FP8 相对 BF16 的时延改善明显小于 batch=4 时，说明 reduction 开销占比过高，需要 CUDA Graph 融合而非继续加批。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-24\">二十四 · 长度分布：序列维度的隐性约束</h3>\n<p>DiT 的“序列长度”由 latent 的空间分辨率与 patch 划分决定，而不是文本 token 数。这意味着长度分布不是随请求变化的随机变量，而是由服务端配置的分辨率档位决定的离散集合。这一点让负载配方比 LLM 场景简单，但也更脆弱：一旦分辨率档位跨过某个阈值，配方的适用性会整体失效。</p>\n<p>失效机制在注意力矩阵乘上。$Q\\cdot K^T$ 的 FLOPs 随序列长度平方增长，而 FP8 路径的数值风险随长度线性累积——softmax 内部虽用 BF16 累加防溢出，但输入到 softmax 的 logits 已经是 FP8 GEMM 的输出，长序列下 logit 的动态范围扩张，per-tensor 的 activation scale 难以同时覆盖大值与小值。校准间隔过长会让 activation scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块。这是配方在长度维度上的硬边界：超长序列与高分辨率下需保留更多 BF16 通道。</p>\n<p>工程上的判别方法是观察校准残差 $\\Delta_{\\text{err}} \\approx \\Delta_{\\text{fp8}}/\\sqrt{N_{\\text{calib}}}$ 随分辨率档位的变化。若提升分辨率后同一校准间隔下的 $\\Delta_{\\text{err}}$ 明显抬升，说明 scale 漂移已经越过安全区，此时要么缩短校准间隔 N，要么对该档位回退部分通道到 BF16，而不是硬扛。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-25\">二十五 · 并发结构与单步时延的耦合</h3>\n<p>DiT 服务的并发模型与自回归解码不同：没有 KV cache 的逐 token 增长，取而代之的是每步全量重算的中间激活。并发请求在服务端被合并成批，批内的 latent 共享同一组权重，但各自持有独立的 per-token scale。这带来一个配方层面的约束：并发数上升时，reduction kernel 的调用次数按 token 数线性增长，而 GEMM 的调用次数按批次数增长。二者的比例决定了 FP8 收益的净额。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>这个式子给出的是理想下界，实际单步时延还要叠加 reduction 与反量化的串行段。在低并发下，$M_{\\text{attn}}/\\text{BW}_{\\text{HBM}}$ 项主导——权重与激活显存减半后，HBM 搬运量下降，这一项确实受益；但 reduction kernel 是纯延迟项，不随带宽改善而缩小。因此低并发时 FP8 的端到端收益会被压缩，而中高并发（批内 token 数足够）时 GEMM 项主导，FP8 Tensor Core 吞吐约为 BF16 的 2 倍的优势才充分释放。</p>\n<p>具体例子：一个以单图时延为 SLO 的服务，若把并发从 1 提到 4 而保持批大小不变（即四个独立批次轮转），单步时延不会改善，反而因调度切换变差；正确做法是把并发合并进同一批次，让 reduction 开销被 4 倍的 GEMM 工作量摊薄。这与连续批处理的思路一致，但 DiT 的批合并粒度受显存约束——中间激活缓存减半后腾出的空间正是用来做这件事的。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-26\">二十六 · 负载错配的三种典型崩法</h3>\n<p>配方之外的三类负载会以不同方式失效，且失效信号各不相同，运维上需要区分对待。</p>\n<ul>\n<li><b>小 batch 高频请求</b>：per-token 动态 scale 的 reduction kernel 未与 CUDA Graph 融合，小 batch 下调度开销吃掉 FP8 收益。表现为 FP8 版本时延与 BF16 持平甚至更差，但 GPU 利用率读数偏低、kernel 启动间隙明显。修法是 CUDA Graph 捕获整个 block 前向，把 reduction 与量化融进图内。</li>\n<li><b>超长序列 / 高分辨率</b>：activation scale 校准间隔过长，长序列注意力出现数值溢出，输出 NaN 或色块。表现为间歇性坏图，且坏图率随分辨率档位上升。修法是缩短校准间隔 N、对该档位保留更多 BF16 通道，而不是全局回退。</li>\n<li><b>画质敏感型请求</b>：softmax 与残差未保留 BF16 累加，FP8 量化误差累积导致 FID 明显退化与注意力图崩坏。表现为整体画质下滑而非局部坏点，注意力可视化上出现结构断裂。修法是检查残差路径是否被误降精度、outlier 通道是否被裁掉。</li>\n</ul>\n<p>三类失效的共同点是：它们都不会在吞吐指标上暴露，只在时延分布尾部或画质指标上体现。因此负载配方的验收不能只看平均吞吐，必须同时看 P99 单步时延与抽样画质。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-27\">二十七 · 与相邻精度档位的负载分工</h3>\n<p>FP8 配方不是孤立存在的，它与 NVFP4 混合精度在同一服务里构成档位分工。相比 BF16 基线，FP8 把 QKV/FFN GEMM 与注意力矩阵乘统一降精度，单步时延降 30%–45%；相比 NVFP4 混合精度，FP8 精度更高、实现更简单，但吞吐只有 FP4 的一半，适合对画质更敏感或 kernel 调优资源有限的场景。</p>\n<p>负载分工的判据是请求的容错预算。高分辨率、长序列、画质敏感型请求落在 FP8 档；短序列、低分辨率、吞吐优先的批量生成落在 FP4 档。分档的代价是权重需要维护两份精度副本，显存占用回升——但权重与激活显存在 FP8 下已减半，这份回升在预算内。更细的做法是按分辨率档位路由：同一模型在高分辨率档走 FP8、低分辨率档走 FP4，路由决策在请求进入时依据 latent 尺寸做出，不进入单步循环。</p>\n<p>规模上限受 softmax 数值稳定性与 reduction 开销约束，这条约束在分档后依然存在：FP8 档的超长序列仍需保留更多 BF16 通道，FP4 档则根本不应承接这类请求。负载配方的本质是把“哪些请求能进哪个精度档”写成显式规则，而不是让所有请求共享一个默认精度。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-28\">二十八 · 配方的可观测性与调参顺序</h3>\n<p>把配方落到运维层面，需要三个可观测量的组合：单步时延的批缩放曲线（判断 reduction 是否被摊薄）、校准残差随分辨率档位的变化（判断 scale 是否漂移）、以及抽样画质的 FID 趋势（判断残差与 outlier 通道是否完好）。三者缺一，调参就会在错误的方向上迭代。</p>\n<p>调参顺序应当是固定的：先固定批大小窗口 1–8 内的一个值，用 CUDA Graph 融合 reduction，确认小 batch 下 FP8 相对 BF16 有时延收益；再按分辨率档位扫校准间隔 N，找到 $\\Delta_{\\text{err}}$ 不随档位抬升的最大 N；最后才动 outlier 通道与 BF16 保留比例，因为这一步直接改变画质，必须在前两步确认数值安全后再做。反过来先调精度保留比例，会把 reduction 开销与数值漂移混在一起，无法归因。</p>\n<p>一个具体的工程判断：若在批大小窗口内、校准间隔已缩短、CUDA Graph 已融合的条件下，FP8 相对 BF16 的单步时延改善仍不足，则说明该负载的注意力与 FFN GEMM 占比不够高——即请求形态本身不在配方内，应回退 BF16 或改走其他精度档，而不是继续在 kernel 层面榨取。这个判断把负载配方从“调优清单”变成了“准入条件”，也是本算法在服务化部署中不被滥用的关键。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-29\">二十九 · 负载配方：FP8 收益只在特定请求形态下成立</h3>\n<p>这套 FP8 方案的经济性并非无条件成立，它把单步时延拆成两个可竞争的项：<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>其中 $M_{\\text{attn}}$ 是 QKV 与中间激活缓存的搬运量，$\\text{TC}_{\\text{fp8}}$ 是 Blackwell 原生 FP8 Tensor Core 吞吐（约为 BF16 的 2 倍）。FP8 同时压低分子（显存减半、搬运减半）与分母（吞吐翻倍），所以只有当请求形态让这两项之一真正成为瓶颈时，30%–45% 的单步时延收益才会兑现。负载配方因此写得很窄：请求形态是 DiT 单步前向的批量 latent 生成，批大小按显存与 SLO 取 1–8，SLO 以单图时延计，并行拓扑以单卡为主、大模型才走张量并行。换句话说，它是为“显存受限、注意力与 FFN GEMM 占主导”的服务化部署设计的，而不是为任意 batch 的通用推理。</p>\n<p>批大小落在 1–8 这个区间是有代价结构的。per-token 动态 scale 需要一次 reduction kernel 求 $\\max|x|$ 再套用<div class=\"formula\">$$x_q=\\text{clamp}\\left(\\text{round}\\left(\\frac{x}{s}\\right),-2^{m-1},2^{m-1}-1\\right),\\qquad s=\\frac{\\max|x|}{2^{m-1}}$$</div>这个 reduction 的绝对开销与 batch 无关，摊到每个 token 上的占比却随 batch 缩小而上升。batch=1 时，QKV 与 FFN GEMM 的 FP8 加速被 scale 计算与 kernel 启动开销部分吃掉，必须靠 CUDA Graph 把整条前向的调度成本摊薄，否则小 batch 下收益趋近于零。反过来，batch 一旦推到显存上限之外，激活缓存与 QKV 中间结果会把 HBM 带宽项重新顶起来，$T_{\\text{step}}$ 从算力受限滑回带宽受限，FP8 的吞吐优势被搬运延迟抵消。真正的甜点区是“激活缓存刚好装下、GEMM 仍算力受限”的那一档，这也是配方把上限压在 8 的原因。</p>\n<p>长度分布与分辨率是另一条边界。长序列注意力让 softmax 的数值动态范围变大，FP8 量化误差在 $Q\\cdot K^T$ 与 $\\text{softmax}\\cdot V$ 上累积，必须保留 BF16 累加与 outlier 通道；校准间隔过长会让 activation scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块。此时要么缩短每 N 步的校准周期、把 reduction 开销重新引入，要么为敏感张量回退到 E5M2 甚至 BF16 通道，两条路都在侵蚀 FP8 的净收益。高分辨率 latent 同理：显存减半带来的“更大 batch 或更高分辨率”额度，会被超长序列所需的额外 BF16 保留通道部分收回。定性地说，序列越长、分辨率越高，方案越向“精度优先”滑移，吞吐红利越薄。</p>\n<p>负载不对时的失效是分层的，可以按症状定位：<table class=\"mini\"><thead><tr><th>负载错配</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>batch 过小（趋近 1）</td><td>per-token scale reduction 未与 CUDA Graph 融合</td><td>调度开销吃掉 FP8 收益，单步时延不降反升</td></tr><tr><td>batch 过大 / 分辨率过高</td><td>激活缓存溢出甜点区，$M_{\\text{attn}}/\\text{BW}_{\\text{HBM}}$ 重新主导</td><td>HBM 带宽受限，吞吐不再随 batch 线性增长</td></tr><tr><td>超长序列 + 校准稀疏</td><td>activation scale 漂移，softmax 数值溢出</td><td>NaN 或色块，需回退 BF16 通道，FID 退化</td></tr><tr><td>softmax/残差未留 BF16 累加</td><td>量化误差沿残差路径累积</td><td>注意力图崩坏，画质掉点不可接受</td></tr></tbody></table>这张表的共同结论是：FP8 的收益上限由负载形态决定，而不是由格式本身决定。相比 NVFP4 混合精度，FP8 精度更高、实现更简单，但吞吐只有 FP4 的一半，适合对画质更敏感或 kernel 调优资源有限的场景——这也意味着当负载已经偏离甜点区时，换更激进的格式并不能救回时延，只会把失效从“慢”变成“坏”。工程判断应落在准入侧：按 batch 与序列长度做请求分档，短序列小 batch 走 CUDA Graph 融合路径，长序列高分辨率保留 BF16 通道并加密校准，把 FP8 只压在它真正能赢的那一档负载上。</p>\n<h3 id=\"alg-fp8-dit-attn-sec-30\">三十 · 硬件档位与算力预算的绑定方式</h3>\n<p>部署配方的第一步不是选框架，而是把硬件档位和算子清单对齐。Blackwell 上 FP8 Tensor Core 吞吐约为 BF16 的 2 倍，这个 2 倍只对“纯 GEMM 且输入已在 FP8 域”的算子成立；一旦 kernel 内部插入 BF16 累加、反量化写回、per-token scale 的 reduction，有效倍率就会被吃掉一截。因此配方里必须显式区分“名义档位”和“有效档位”：名义上 QKV 投影、$Q\\cdot K^T$、$\\text{softmax}\\cdot V$、FFN 两级 GEMM 全部走 FP8，有效上 softmax 内部仍是 BF16 累加路径，残差加法与 LayerNorm 也在 BF16 域，这些段落不享受 2 倍。工程判断是：把单步时间按算子分桶估算，GEMM 桶用 $\\text{FLOPs}_{\\text{bf16}}/2$ 折算，非 GEMM 桶按 BF16 原样计入，再决定是否需要把某些层回退。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>这个 max 结构说明档位选择的两条腿：高分辨率 latent 下 $M_{\\text{attn}}$ 项（注意力中间张量的 HBM 往返）先饱和，此时换更快的 Tensor Core 档位没有收益，收益来自把 QKV 与中间激活缓存压到 FP8 使字节数减半；低分辨率、大 batch 下 FLOPs 项先饱和，档位升级才直接兑现。举例：同一 DiT block 在 1024 分辨率 latent 上，注意力矩阵乘的读写量随 token 数平方增长，配方应优先保证这部分缓存的 FP8 存放与连续布局，而不是去追更高的时钟档位。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-31\">三十一 · 并行拓扑：单卡优先与张量并行的切分边界</h3>\n<p>DiT 单步前向的并行拓扑以单卡为主，这是由 batch 规模决定的：批大小按显存与 SLO 取 1–8，单图时延是 SLO 口径，跨卡切分带来的通信延迟在小 batch 下无法被计算掩盖。只有当模型参数量超出单卡权重容量时，才走张量并行，并且切分边界要落在 FP8 GEMM 的列维上——QKV 投影按输出通道切、FFN 第一级按中间维切，使每张卡持有完整的 per-channel scale 向量，避免跨卡同步 scale。切在残差或 LayerNorm 上会强制每步做 BF16 all-reduce，把 FP8 省下的带宽又还回去。</p>\n<ul>\n<li>拓扑决策顺序：先算权重显存（FP8 下减半）能否单卡容纳 → 再看激活缓存与 KV 缓存峰值 → 最后看单步时延是否满足 SLO。</li>\n<li>张量并行度取 2 或 4 时，每卡 GEMM 的 M 维不变、N 维变小，FP8 Tensor Core 的利用率随 N 减小而下降，需保证切分后单卡 N 仍能填满一个 MMA tile。</li>\n<li>通信代价：张量并行每层一次 all-reduce，NVLink 5 域内可接受；跨节点则必须改用分离式部署，把预填与解码放到不同卡组。</li>\n</ul>\n<p>具体例子：一个 FFN 中间维为 $4d$ 的 DiT block，在 4 卡张量并行下每卡承担 $d$ 的中间维，若 $d$ 小于 MMA tile 的 N 维，则每卡 GEMM 出现尾部浪费，此时宁可降到 2 卡并行、把剩余显存留给更大 batch。这是吞吐与单图时延之间的直接换算，不是参数调优的偏好问题。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-32\">三十二 · 量化方案的组合与校准节奏</h3>\n<p>量化方案在配方里是三元组：权重 E4M3、激活 E4M3、敏感张量 E5M2，残差与 LayerNorm 保持 BF16。权重用 per-channel scale，激活用 per-token 动态 scale，两者在 GEMM 前的量化 kernel 中完成。缩放公式为：</p>\n<div class=\"formula\">$$x_q=\\text{clamp}\\left(\\text{round}\\left(\\frac{x}{s}\\right),-2^{m-1},2^{m-1}-1\\right),\\qquad s=\\frac{\\max|x|}{2^{m-1}}$$</div>\n<p>校准节奏是配方中最容易被忽略的一项。activation scale 每 N 步校准一次并写回缓存供后续 step 复用，N 过大则 scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块；N 过小则每步都触发 reduction 与写回，小 batch 下调度开销吃掉 FP8 收益。误差随校准样本数的收敛关系给出选 N 的依据：</p>\n<div class=\"formula\">$$\\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}}$$</div>\n<p>工程上把 N 绑定到采样步数与 CFG 批合并后的实际前向次数，而不是绑定到 wall-clock；因为扩散采样的 timestep embedding 在每步变化，scale 的统计分布随 timestep 漂移，按步数校准比按时间校准更稳。代价面：per-token 动态 scale 引入额外 reduction kernel，必须与 CUDA Graph 融合以摊薄调度成本，否则小 batch 下这块开销会显著拖慢单步。举例：batch=1 时 reduction kernel 的启动延迟与 GEMM 本身同量级，融合进图后这部分被隐藏；batch=8 时 GEMM 占比上升，reduction 相对占比下降，融合收益变小但仍应保留。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-33\">三十三 · KV 策略：QKV 缓存与中间激活缓存的容量换算</h3>\n<p>这里的 KV 不是自回归意义上的 KV cache，而是 DiT 单步内的 QKV 张量与跨 step 复用的中间激活缓存。权重与激活显存减半后，同一张卡可容纳更大 batch 或更高分辨率 latent，配方要在这两者之间做显式分配，而不是让框架默认吃满。容量换算的思路是：先固定分辨率，算出单样本的 QKV 与 FFN 中间张量字节数（FP8 下为 BF16 的一半），再除以可用显存得到 batch 上限；若 batch 上限低于 SLO 所需并发，则降低分辨率或启用分块注意力。</p>\n<table class=\"mini\"><thead><tr><th>缓存对象</th><th>精度</th><th>复用方式</th><th>失效条件</th></tr></thead><tbody><tr><td>QKV 张量</td><td>E4M3</td><td>单步内即用即弃</td><td>分辨率或 batch 变化</td></tr><tr><td>FFN 中间激活</td><td>E4M3</td><td>单步内即用即弃</td><td>—</td></tr><tr><td>activation scale</td><td>FP32 标量</td><td>跨 step 复用，每 N 步刷新</td><td>校准间隔超限、timestep 漂移</td></tr><tr><td>残差与 LayerNorm 输出</td><td>BF16</td><td>单步内即用即弃</td><td>—</td></tr></tbody></table>\n<p>代价面：QKV 缓存按 FP8 存放使 HBM 读写字节减半，直接缓解 $M_{\\text{attn}}/\\text{BW}_{\\text{HBM}}$ 项；但 scale 缓存是 FP32 标量，per-token 意味着每个 token 一个标量，token 数大时这部分虽小却破坏访存连续性，配方中应把 scale 与量化张量分开存放、按块对齐。具体例子：高分辨率 latent 下 token 数上升，若把 scale 与 QKV 交错存放，每次 GEMM 前的读取会产生跨步访问，带宽利用率下降；分离存放后读取是两次连续流，代价可控。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-34\">三十四 · 调度参数与可复现配置思路</h3>\n<p>调度参数在 DiT 服务里主要管三件事：批的组成、CUDA Graph 的捕获边界、以及校准与采样的交错。批按 1–8 取，SLO 以单图时延计，因此批内不应混入不同分辨率的 latent——混合分辨率会让 GEMM 的 M 维不齐，FP8 kernel 走尾部路径，单步时延被最慢样本拖住。CUDA Graph 的捕获边界应覆盖“量化 kernel + GEMM + softmax BF16 累加 + 反量化 + 残差”这一整段，把 per-token reduction 一起圈进去；校准 kernel 放在图外，因为它每 N 步才触发一次，进图会引入条件分支。</p>\n<ul>\n<li>可复现配置的书写顺序：硬件档位（Blackwell，FP8 有效倍率按算子分桶折算）→ 并行拓扑（单卡或张量并行度及切分维）→ 量化三元组与 scale 粒度 → 校准间隔 N 与触发条件 → KV 缓存精度与容量分配 → 批上限与分辨率档 → CUDA Graph 捕获范围。</li>\n<li>每个参数都要带一个可观测的判据：张量并行度看单卡 N 是否填满 tile；校准间隔看长序列注意力是否出现溢出；批上限看显存峰值是否留出残差余量。</li>\n<li>失败模式回退路径：若 FID 明显退化，先检查 softmax 与残差是否确实保留 BF16 累加与 outlier 通道，再检查 scale 是否漂移；若单步时延未达预期，先看 reduction 是否已进图，再看 GEMM 桶的有效倍率是否被非 GEMM 段稀释。</li>\n</ul>\n<p>具体例子：一个面向画质敏感场景的配方——单卡、batch=4、分辨率固定、权重与激活 E4M3、敏感张量 E5M2、残差 BF16、校准间隔按采样步数取固定值、CUDA Graph 覆盖整段前向。其单步时延相对 BF16 基线降 30%–45%，显存减半后 batch 从 2 提到 4；若把校准间隔拉长以省 reduction，长序列注意力先出现溢出而非画质缓慢退化，这是配方中必须设的硬边界。相比 NVFP4 混合精度，FP8 精度更高、实现更简单，但吞吐只有 FP4 的一半，适合对画质更敏感或 kernel 调优资源有限的场景；这条判断直接决定档位选择，而不是事后调参。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-35\">三十五 · 部署配方的失效边界：FP8 DiT 在什么条件下会反噬</h3>\n<p>这套配方的骨架是：硬件档位锁定 Blackwell，靠原生 FP8 Tensor Core 把 QKV/FFN GEMM 与 $Q\\cdot K^T$、$\\text{softmax}\\cdot V$ 统一降到 E4M3 执行，残差与 LayerNorm 留在 BF16，E5M2 只承接梯度类敏感张量；并行拓扑以单卡为主，只有参数量撑爆单卡显存时才切张量并行；KV 策略指的不是自回归意义上的 KV cache，而是 QKV 投影输出与中间激活缓存——权重与激活显存减半后，同一张卡可以容纳更大 batch 或更高分辨率 latent。但配方成立的前提是三个不等式同时被满足，任何一条被打破，FP8 的收益就会被自身的开销吃掉。第一个不等式是算力侧：$\\text{FLOPs}_{\\text{eff}}=\\text{FLOPs}_{\\text{bf16}}/2$ 只在 Tensor Core 真正跑满时兑现，若 kernel 因 softmax 的 BF16 累加与反量化插桩而频繁停顿，有效吞吐会跌回 BF16 水平。第二个是带宽侧，单步时延的下界由 $T_{\\text{step}}\\approx\\max\\left(M_{\\text{attn}}/\\text{BW}_{\\text{HBM}},\\ \\text{FLOPs}/\\text{TC}_{\\text{fp8}}\\right)$ 给出：当分辨率推高、序列变长，$M_{\\text{attn}}$ 项主导，此时降精度省下的显存带宽才是主要收益来源，而不是 Tensor Core 吞吐。第三个是数值侧，$\\Delta_{\\text{err}}\\approx\\Delta_{\\text{fp8}}/\\sqrt{N_{\\text{calib}}}$ 说明校准样本数 $N_{\\text{calib}}$ 直接决定 scale 的可信度，校准间隔拉长等价于 $N_{\\text{calib}}$ 失效，activation scale 漂移会让长序列注意力出现数值溢出，输出 NaN 或色块。</p>\n<p>失效条件可以按代价类型归类，工程上最该警惕的是小 batch 下的 reduction 反噬。per-token 动态 scale 要求对每个 token 的激活求 $\\max|x|$ 再算 $s=\\max|x|/(2^{m-1})$，这是一个独立的 reduction kernel；batch 取 1–8 时，GEMM 本身的有效工作量很小，reduction 的启动与同步开销占比上升，若没有与 CUDA Graph 融合摊薄调度成本，FP8 省下的时间会被调度开销整段吃掉。第二类失效是数值性的：softmax 内部必须保留 BF16 累加以防溢出，残差路径必须保留 BF16 与 outlier 通道，一旦为了追求“全 FP8”而把这两处也降精度，量化误差沿残差累积，FID 明显退化、注意力图崩坏——这不是精度微降，而是结构性失效。第三类是拓扑性的：张量并行在大模型上是必要的，但 FP8 下的 TP 通信量并未减半（激活仍是 BF16 通信或需额外量化/反量化），当 TP 度数与 NVLink 域跨出单机柜时，通信延迟会重新成为 $T_{\\text{step}}$ 的瓶颈项，抵消 GEMM 侧的 30%–45% 单步时延收益。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>触发信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>小 batch（1–8）</td><td>reduction kernel 占比升高</td><td>调度开销吃掉 FP8 收益</td><td>CUDA Graph 融合，固定 shape 捕获</td></tr><tr><td>softmax/残差降精度</td><td>FID 退化、注意力图崩坏</td><td>画质不可接受</td><td>BF16 累加 + outlier 通道保留</td></tr><tr><td>校准间隔过长</td><td>长序列 NaN、色块</td><td>整批输出报废</td><td>缩短 N 步校准，写回缓存复用</td></tr><tr><td>高分辨率/超长序列</td><td>$M_{\\text{attn}}$ 项主导</td><td>带宽而非算力成瓶颈</td><td>保留更多 BF16 通道，慎扩 TP</td></tr></tbody></table>\n<p>与相邻方案的取舍决定了这套配方的适用上限。相比 BF16 基线，FP8 把 QKV/FFN GEMM 与注意力矩阵乘统一降精度，单步时延降 30%–45%，这是配方的主收益；相比 NVFP4 混合精度，FP8 精度更高、实现更简单，但吞吐只有 FP4 的一半，因此它适合对画质更敏感、或 kernel 调优资源有限、不愿为 FP4 的 scale 搜索与异常值处理投入工程量的团队。可复现的配置思路应当写成“档位—开关—阈值”三段：档位固定 Blackwell 单卡优先、TP 仅在显存不足时开启；开关包括 per-token 动态 scale、softmax BF16 累加、残差 BF16 回加、每 N 步校准写回缓存四项，前两项不可关闭；阈值则以单图时延 SLO 为唯一判据，当实测 $T_{\\text{step}}$ 的 reduction 占比超过 GEMM 收益时回退到 BF16 路径或增大 batch 摊薄。真正需要盯住的不是峰值吞吐，而是校准间隔与 batch 的乘积效应：batch 越小、校准越稀，$\\Delta_{\\text{err}}$ 的放大越不可控，此时宁可牺牲部分时延也要缩短校准周期，把数值稳定性换回来。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-36\">三十六 · 配方落地时的边界条件与代价核算</h3>\n<p>这套配方在部署侧真正决定成败的不是“能不能跑 FP8”，而是三个耦合的边界：batch 大小、序列长度、校准节奏。硬件档位选 Blackwell 单卡起步，仅当 DiT 主干参数量超出单卡 HBM 容量或单步时延被单卡 Tensor Core 吞吐卡死时才切张量并行——因为 TP 会引入每层 GEMM 后的 all-reduce，把本就紧张的通信预算再切一刀。批大小按显存与单图 SLO 取 1–8，这个区间不是随意给的：小 batch 下 per-token 动态 scale 的 reduction kernel 占比上升，单步时延里出现一块与计算无关的固定开销，必须用 CUDA Graph 把量化、reduction、GEMM launch 一并捕获，否则调度成本会吃掉 FP8 带来的那部分收益。量化方案固定为 E4M3 承载权重与激活、E5M2 承载敏感张量，残差与 LayerNorm 留在 BF16，这是不可协商的底线。</p>\n<p>单步时延的解析式给出配方调参的方向：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>当注意力中间激活的搬运量 $M_{\\text{attn}}$ 主导时，FP8 把权重与激活显存减半的收益直接体现在这一项上，批大小可以往上顶；当 FLOPs 项主导时，收益来自 FP8 Tensor Core 相对 BF16 约 2 倍的吞吐，单步时延降 30%–45% 的区间就落在这里。工程判断是：先测出当前负载落在 max 的哪一侧，再决定是加 batch 还是加分辨率，盲目两边一起推会让 reduction 开销和 softmax 数值风险同时放大。</p>\n<p>失效条件有三条，每条都对应一个可观测信号。其一，softmax 与残差若未保留 BF16 累加与 outlier 通道，量化误差沿 step 累积，表现为 FID 明显退化与注意力图崩坏——这是画质敏感场景必须留 BF16 通道的原因。其二，per-token scale 的 reduction 未与 CUDA Graph 融合，小 batch 下调度开销反噬，表现为 batch=1 时时延不降反升。其三，activation scale 校准间隔过长，scale 随 timestep 漂移，长序列注意力出现数值溢出，输出 NaN 或色块；校准间隔 $N$ 与误差的关系可写成 $\\Delta_{\\text{err}} \\approx \\Delta_{\\text{fp8}}/\\sqrt{N_{\\text{calib}}}$，缩短 $N$ 能压误差但增加校准 kernel 的调用频次，需在 SLO 允许的抖动范围内取折中。相比 NVFP4 混合精度，FP8 精度更高、实现更简单，但吞吐只有 FP4 的一半，适合画质敏感或 kernel 调优资源有限的团队。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>取值/边界</th><th>代价落点</th></tr></thead><tbody><tr><td>硬件档位</td><td>Blackwell 单卡；超容量才 TP</td><td>TP 引入 all-reduce 通信</td></tr><tr><td>批大小</td><td>1–8，按显存与单图 SLO</td><td>小 batch reduction 占比高</td></tr><tr><td>量化</td><td>E4M3 权重/激活，E5M2 敏感张量</td><td>softmax/残差须 BF16 累加</td></tr><tr><td>校准间隔</td><td>每 N 步写回 scale</td><td>过长则长序列溢出</td></tr></tbody></table>\n<h3 id=\"alg-fp8-dit-attn-sec-37\">三十七 · 单步时延的两条腿：HBM 带宽与 FP8 张量核吞吐</h3>\n<p>把 DiT 单步前向拆成算子图后，真正决定 $T_{\\text{step}}$ 的只有两个物理量：一次 step 必须搬动的字节数 $M_{\\text{attn}}$（QKV 投影的权重与激活、注意力矩阵、FFN 两级权重、残差与 LayerNorm 中间量）和必须完成的 FP8 乘加次数。Blackwell 上 FP8 Tensor Core 吞吐约为 BF16 的两倍，因此 GEMM 侧的时间预算被压掉一半，剩下的瓶颈就转移到搬运上。用 roofline 形式写出来：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>这个 max 的含义是：FP8 把第二项砍半之后，第一项开始主导，于是“精度换吞吐”的收益不再线性兑现，而是被显存带宽封顶。工程判断很直接——在 batch=1、分辨率中等的单图请求下，QKV 投影与 FFN 的权重读取量是固定成本，激活量随 batch 线性增长；权重占大头时，FP8 减半权重显存同时也减半权重读取字节，这一步是净赚；而注意力矩阵 $Q\\cdot K^T$ 的中间结果随序列长度平方增长，它落在片上还是落在 HBM，决定了 max 里哪一项胜出。因此把 $Q\\cdot K^T$ 与 $\\text{softmax}\\cdot V$ 做成融合的 FP8 注意力、让中间矩阵不落 HBM，是把 $M_{\\text{attn}}$ 压下来的关键动作，而不是继续堆张量核利用率。</p>\n<p>具体例子：一个以注意力与 FFN GEMM 占主导的 DiT block 栈，权重与激活统一降到 E4M3 后显存减半，同一张卡上可容纳更大 batch 或更高分辨率 latent；但若注意力中间矩阵仍按 BF16 写回 HBM，则单步时延的下降幅度会被这项搬运吃掉，实测收益落在 30%–45% 区间的下沿。反过来，融合注意力加上 CUDA Graph 固化调度后，收益才靠近上沿。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-38\">三十八 · 显存账本：权重、激活缓存与 QKV 中间态的三层占用</h3>\n<p>FP8 部署后的显存不是“减半”一句话能概括的，它分三层且各层行为不同。第一层是权重：E4M3 权重加 per-channel scale，字节数为 BF16 的一半，是静态占用，直接决定能否装下模型与张量并行的切分粒度。第二层是 QKV 与中间激活缓存：这些张量按 batch 与序列长度动态增长，FP8 化后单元素字节减半，于是同样的显存可以支撑更大 batch 或更高分辨率 latent——这正是服务化部署里最想要的弹性。第三层是必须保留 BF16 的部分：残差流、LayerNorm 输出、softmax 内部累加，它们不参与减半，占比虽小但在长序列下随 token 数线性上升，成为显存账本里不可压缩的底噪。</p>\n<p>代价体现在碎片化上。per-token 动态 scale 需要为每个 token 存一个标量，per-channel 权重 scale 需要为每个输出通道存一个标量；这些 scale 张量本身很小，但它们打断了连续大块分配，让显存池出现大量小片。在 batch=1–8 的 DiT 单步负载下，这种碎片不会致命，但当并行拓扑从单卡走向张量并行、每卡只持有切片权重时，scale 张量的对齐与填充会放大通信缓冲区的尺寸。工程上的处理是把 scale 与对应张量打包进同一块连续缓冲、按 128 元素或 256 元素粒度对齐，使反量化 kernel 一次读取即可拿到数据与 scale，避免二次访存。</p>\n<p>具体例子：把 QKV 与中间激活缓存按 FP8 存储后，原本只能跑 batch=2 的显存水位可以推到 batch=4 以上，单图时延不变而吞吐翻倍；但若残差与 LayerNorm 也被误降精度，则必须额外保留 outlier 通道，显存账本反而多出一层稀疏补偿结构，抵消掉一部分收益。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-39\">三十九 · 通信面：张量并行下的 FP8 集合通信与 scale 同步</h3>\n<p>单卡能装下的 DiT 走单卡，装不下才走张量并行；一旦切分，通信就从可忽略项变成时延主项之一。FP8 在这里有一个天然优势：all-reduce 与 all-gather 搬运的是 E4M3 字节，消息体积是 BF16 的一半，NVLink 5 上的集合通信时间近似按字节线性缩放，于是通信预算直接减半。但优势有前提——归约必须在高精度累加域完成。若把 FP8 张量直接做环形归约，累加误差会随并行度增长，残差流被污染后 FID 退化，这与 softmax 不保留 BF16 累加是同一类失败。正确做法是通信前反量化到 BF16 做归约、归约后再量化回 FP8，代价是通信链路上多一次转换 kernel。</p>\n<p>第二个通信面是 scale 同步。per-token 动态 scale 是局部统计量，在张量并行下每个 rank 只看到自己切片的 token 子集，若各 rank 独立量化再拼接，拼接后的激活分布与单卡不一致，GEMM 结果出现系统性偏差。解决办法是在量化前做一次跨 rank 的 max 归约，把全局最大绝对值同步到所有 rank，再各自计算 $s=\\max|x|/2^{m-1}$。这次归约是标量级的，字节极小但引入一次同步点，在流水线里表现为一个气泡；把它与上一层的计算重叠、或按固定间隔批量同步多个层的 scale，可以把气泡摊薄。</p>\n<p>具体例子：张量并行度为 4 的 DiT，若每层量化前同步一次 scale，单步内多出若干次标量 all-reduce，每次延迟虽小但串行叠加后吃掉一部分 FP8 收益；改为每 N 步校准一次 activation scale 并写回缓存供后续 step 复用，同步次数下降一个量级，长序列下的数值稳定性靠校准间隔而非每步同步来保证——但间隔过长会让 scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-40\">四十 · 功耗与热：吞吐翻倍不等于每瓦吞吐翻倍</h3>\n<p>FP8 Tensor Core 吞吐约为 BF16 的两倍，但功耗不是。张量核在 FP8 模式下单位时间完成的乘加翻倍，功率随之上升；而 HBM 侧的搬运功耗与字节数成正比，FP8 减半字节确实省下这部分。净效果取决于算子图的算术强度：GEMM 密集段算术强度高，功耗由张量核主导，每瓦吞吐提升明显；注意力与逐元素段算术强度低，功耗由 HBM 与片上网络主导，FP8 的省电主要体现在搬运上。在 GB200/GB300 NVL72 这类整机柜形态里，功耗预算是机柜级共享的，单卡省下的瓦数会转化为可部署的卡数或可维持的持续频率。</p>\n<p>热约束的工程表现是持续频率跌落。短时突发的 FP8 峰值吞吐不能作为容量规划依据；持续负载下张量核频率受限于散热，实际可持续吞吐低于峰值。容量规划时应按持续吞吐而非峰值吞吐折算单图时延，否则 SLO 在长时间运行后失守。一个可操作的判断是：把 FP8 带来的 30%–45% 单步时延下降中的一部分预留为热降频余量，只把剩余部分计入 SLO 承诺。</p>\n<p>具体例子：同一台机器在冷态下跑 batch=8 的 DiT 单步，FP8 路径时延明显低于 BF16；连续运行进入热稳态后两者差距收窄，因为 BF16 路径本就未打满张量核、受热影响小，而 FP8 路径贴着功耗墙跑更容易被降频。这提示调度器应把 FP8 路径的 batch 上限按热稳态标定，而不是按冷态峰值标定。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-41\">四十一 · 尾延迟：小 batch 的 reduction 开销与调度气泡</h3>\n<p>DiT 服务化部署的 SLO 以单图时延计，请求形态是 batch=1–8 的批量 latent 生成，这意味着系统长期运行在小 batch 区间。小 batch 恰恰是 FP8 收益最脆弱的地方：per-token 动态 scale 需要一个 reduction kernel 求每 token 的最大绝对值，这个 kernel 的启动与同步开销是固定的，不随 batch 缩小而缩小。batch 越小，GEMM 本身越快，reduction 在单步时延中的占比越高，极端情况下调度开销吃掉全部 FP8 收益。失败模式很明确——reduction kernel 未与 CUDA Graph 融合，小 batch 下调度开销吃掉 FP8 收益。</p>\n<p>尾延迟的来源还有量化与反量化的边界 kernel。每个 FP8 GEMM 前有一次量化、后有一次反量化加回 BF16 残差，这些逐元素 kernel 的网格尺寸随 token 数变化，在小 batch 下网格过小、SM 占用率低，形成短促但密集的气泡。把量化融进前一个算子的 epilogue、把反量化融进 GEMM 的 epilogue，可以消掉这些独立 kernel；配合 CUDA Graph 把整个 step 的 kernel 序列固化为一次提交，调度成本被摊薄到接近零。这是把 FP8 收益从“峰值”变成“尾延迟可承诺”的必要条件。</p>\n<p>具体例子：batch=1 的单图请求，若量化、GEMM、反量化各自独立启动，单步内 kernel 数量翻倍，尾延迟的 P99 被调度抖动拉长；融合 epilogue 加 CUDA Graph 后，kernel 数量回落，P99 与 P50 的差距收窄，SLO 才可稳定承诺。校准间隔与尾延迟也相关：每 N 步校准一次 activation scale 的那一步会插入额外的统计 kernel，形成周期性的时延长尾，调度上应把校准步安排在低峰或与缓存写回合并。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-42\">四十二 · 规模上去以后哪里先崩：四个依次触发的约束</h3>\n<p>把 batch、分辨率、序列长度、并行度同时推高，崩溃点有固定顺序。第一崩的是 softmax 数值稳定性：序列变长后注意力分数动态范围扩大，FP8 的 E4M3 尾数位宽不足以承载，若 softmax 内部不保留 BF16 累加与 outlier 通道，注意力图崩坏、FID 明显退化先于任何性能问题出现。第二崩的是 reduction 开销占比：batch 增大后 reduction 的相对成本下降，但序列变长使 per-token scale 的数量线性上升，reduction kernel 的绝对时间重新抬头。第三崩的是显存：残差与 LayerNorm 的 BF16 底噪随 token 数线性增长，加上 scale 张量的碎片化，显存水位先于带宽打满。第四崩的才是通信：张量并行度提高后，scale 同步的串行气泡与集合通信的字节量共同把单步时延推高。</p>\n<p>这个顺序给出容量规划的判据：不要按峰值吞吐线性外推可支撑的规模，而应按最先进触发的那条约束定档。若目标是长序列高分辨率，优先投入的是 softmax 的 BF16 累加路径与 outlier 通道，而不是继续压 GEMM 精度；若目标是高吞吐服务化，优先投入的是 CUDA Graph 融合与 epilogue 量化，把 reduction 与边界 kernel 消掉；若目标是多卡大模型，优先投入的是 scale 同步的批量化与通信前的 BF16 归约路径。规模上限受 softmax 数值稳定性与 reduction 开销约束，超长序列与高分辨率下需保留更多 BF16 通道——这不是调参问题，而是精度预算在算子图上的重新分配。</p>\n<p>具体例子：把分辨率与序列长度同时推高的一档负载，最先观测到的异常是注意力图局部饱和与色块，对应 softmax 累加精度不足；此时把 $Q\\cdot K^T$ 的输出在 BF16 域累加、只让乘加走 FP8，异常消失而 GEMM 吞吐收益保留大半。再往上推，观测到的是单步时延的周期性长尾，对应校准步插入的统计 kernel，把校准与缓存写回合并后长尾消失。再往上，显存水位先撞墙，此时减半的权重已经省过，剩下能压的只有中间激活缓存的分块复用。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-43\">四十三 · 规模上去以后，先崩的是 reduction 与 softmax 的数值余量</h3>\n<p>单卡、batch 1–8 的服务化配方里，FP8 的账很好算：权重与激活显存减半，QKV/FFN GEMM 与注意力矩阵乘统一降到 E4M3，Tensor Core 吞吐约为 BF16 的两倍，单步时延降 30%–45%。但这条曲线不是线性的。把 batch 推大、把 latent 分辨率推高、把序列拉长，第一个塌陷点不在 GEMM 本身，而在 per-token 动态 scale 的 reduction kernel 与 softmax 的 BF16 累加余量。前者是纯带宽与调度开销，后者是数值余量，两者都不随 Tensor Core 吞吐一起变好。用单步时间下界看得很清楚：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>GEMM 项随 FP8 吞吐翻倍而收缩，$M_{\\text{attn}}$ 项却由激活搬运量决定。激活显存减半确实压低了这一项，但 per-token scale 要为每个 token 求一次 $\\max|x|$ 再写回，等于在 QKV 投影前插入一趟额外的读-归约-写；小 batch 时这趟 kernel 的固定调度成本占比上升，必须与 CUDA Graph 融合才能摊薄，否则 FP8 省下的时间被 reduction 吃掉。batch 增大后 reduction 摊薄，但 softmax 的 BF16 累加与 outlier 通道保留比例随序列长度上升——超长序列与高分辨率 latent 下需要保留更多 BF16 通道，等于把一部分 GEMM 又推回 BF16 吞吐，有效算力收益被稀释。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先受压的资源</th><th>失效表现</th></tr></thead><tbody><tr><td>batch 1–2</td><td>kernel 调度 / 尾延迟</td><td>reduction 开销占比高，FP8 收益被抵消</td></tr><tr><td>batch 增大</td><td>HBM 带宽（激活搬运）</td><td>scale 读写与反量化流量上升</td></tr><tr><td>序列/分辨率拉长</td><td>softmax 数值余量</td><td>校准间隔过长时 scale 漂移、溢出、NaN 或色块</td></tr><tr><td>张量并行跨卡</td><td>NVLink 通信</td><td>FP8 张量需统一 scale 语义，all-reduce 前后插入量化/反量化</td></tr></tbody></table>\n<p>再往上走，单卡放不下就得上张量并行，通信成为新的下界：FP8 权重与激活跨卡切分后，all-reduce 的字节数虽随精度减半，但每张卡都要在集合通信前后插入量化与反量化，通信与计算的重叠窗口被这些标量操作切碎，尾延迟由最慢的那条 rank 决定。功耗侧同样不线性：FP8 Tensor Core 的能效优势在 GEMM 密集段明显，可一旦 BF16 通道比例上升、reduction kernel 频繁唤醒 HBM，单位 token 的能耗曲线会重新抬头。工程判断是：把 FP8 的适用边界画在“GEMM 占主导且序列长度可控”的区间内，校准间隔按序列长度而非固定步数设定，并在 batch 小于阈值时强制走 CUDA Graph 融合路径——规模上去以后先崩的从来不是峰值算力，而是这些不随算力一起缩放的固定开销与数值余量。</p>\n<h3 id=\"alg-fp8-dit-attn-sec-44\">四十四 · 精度失败模式：从 FID 退化到注意力图崩坏</h3>\n<p>FP8 路径的精度失败不是均匀的噪声抬升，而是有明确的结构性来源。第一类是 softmax 与残差链路上的累加精度丢失：若把 $Q\\cdot K^T$ 的累加器或 softmax 内部累加一并降到 FP8，E4M3 的动态范围在长序列上不足以承载 logits 的极值分布，量化误差在 softmax 指数化后被放大，表现为注意力图出现整行塌缩或局部过饱和，最终在生成结果上是 FID 明显退化与纹理崩坏。第二类是 outlier 通道未保留：per-tensor scale 被少数大幅值通道主导，导致其余通道的有效位数被压缩，残差支路上的小幅值更新被系统性抹平，表现为画面整体偏灰、细节丢失而非明显噪点。</p>\n<p>诊断这类问题不能只看端到端指标。工程上应把每个 DiT block 的 FP8 输出与 BF16 参考输出做逐张量相对误差统计，重点看 softmax 前的 logits 张量与残差相加前的 FFN 输出：前者误差抬升意味着 QK 路径的 scale 或累加精度有问题，后者抬升意味着 FFN 反量化或 per-channel scale 失配。校准质量本身可以量化，误差随校准样本数的收敛关系为</p>\n<div class=\"formula\">$$\\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}}$$</div>\n<p>即校准样本翻四倍才能把误差减半，这解释了为什么少量 prompt 校准出的 activation scale 在分布外请求上会明显漂移。具体例子：某服务在 batch=1、分辨率切换后出现固定位置的色块，逐层比对发现是某一 block 的 per-token scale 由单个极端 token 决定，把该 block 改为 per-channel 加 outlier 通道保留后消失。代价上，保留 BF16 累加与 outlier 通道会让该 block 的 Tensor Core 利用率下降，单步时延相对纯 FP8 路径回退，这是精度换时延的直接账。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-45\">四十五 · 显存与 OOM：激活缓存与 KV 的双重压力</h3>\n<p>FP8 把权重与激活显存减半，但 OOM 仍会发生，原因在于 DiT 推理的显存峰值不在权重而在中间激活与 QKV 缓存。每 N 步校准一次 activation scale 并写回 KV/中间缓存供后续 step 复用，这个复用策略在长序列与高分辨率 latent 下会让缓存随步数线性增长；同时 per-token 动态 scale 需要保留一份未量化的 BF16 激活用于 reduction，等于在峰值时刻同时驻留两份张量。批大小按显存与 SLO 取 1–8，实际可用 batch 往往由这个瞬时峰值而非稳态占用决定。</p>\n<p>诊断 OOM 要区分三类：一是稳态权重与缓存超限，表现为启动即失败；二是单步峰值超限，表现为跑到第 k 步才崩，且 k 与序列长度相关；三是碎片化，表现为空闲显存总量足够但分配失败。工程手段是给缓存设硬上限并按步数做环形复用，把校准写回从“每步全量”改为“仅保留最近窗口”，并在 profiler 里记录每个 block 的峰值分配点。系统代价明确：缓存上限收紧会降低跨步复用的命中率，等价于把部分计算从复用路径退回重算，单步 FLOPs 上升；而放宽上限则直接压缩可服务 batch，吞吐下降。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-46\">四十六 · 批抖动与 reduction 开销：小 batch 的收益陷阱</h3>\n<p>per-token 动态 scale 引入额外 reduction kernel，其开销与 token 数成正比但与 GEMM 的计算量不成比例，因此在小 batch 下占比急剧上升。单步时延的实际上界由两条路径的最大值决定：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>当 batch 很小，GEMM 侧远未打满 Tensor Core，时间被 reduction 与 kernel 启动开销主导，FP8 相对 BF16 的理论 2 倍吞吐无法兑现，甚至出现 FP8 比 BF16 更慢的反常。批抖动的典型表现是同一模型在 batch=1 与 batch=4 之间时延不按比例缩放，P99 在小 batch 请求上反而更差。诊断方法是把单步拆成 reduction、GEMM、softmax、反量化四段分别计时，看 reduction 占比是否随 batch 下降而上升。</p>\n<p>解法核心是把 reduction 与 CUDA Graph 融合，把多次小 kernel 启动摊薄成一次图执行，同时把 per-token scale 的计算折叠进 LayerNorm 的 epilogue，避免额外的读写往返。具体例子：某部署在 batch=1 时 reduction 段占总时延的比例高到吃掉全部 FP8 收益，融合进 CUDA Graph 并把 scale 计算并入前一个 kernel 后，小 batch 路径恢复正向收益。代价是 CUDA Graph 要求输入形状稳定，混合分辨率补丁调度会破坏图的复用，需要在分辨率切换点重建图，重建本身带来一次性延迟尖刺。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-47\">四十七 · 路由不均与尾延迟尖刺</h3>\n<p>尾延迟尖刺有三个来源。其一是校准触发的同步点：每 N 步校准一次 activation scale，若校准步恰好落在请求关键路径上，该步时延显著高于邻步，形成周期性尖刺；诊断上应把校准步打上标记，观察 P99 是否与校准周期对齐。其二是张量并行下的路由不均：大模型走张量并行时，QKV 与 FFN 的切分若与 per-channel scale 的通道分布不匹配，某些 rank 承载更多 outlier 通道，其反量化与 reduction 工作量高于同伴，形成 rank 间等待，整体时延由最慢 rank 决定。其三是批内长度不均：连续批处理把长短序列混在一批，注意力矩阵乘的有效利用率被最长序列拉低，短请求被迫等待。</p>\n<p>诊断路由不均要在 rank 级别采集每层 GEMM 的实际耗时与 reduction 耗时，比较最大值与中位数；若差异稳定存在，说明切分策略而非负载波动是根因。缓解手段包括按通道幅值重排切分、把 outlier 通道集中到固定 rank 并给该 rank 更小的 GEMM 分片，以及在批调度侧对长度做分桶。系统代价是重排切分需要一次性离线统计与权重重布局，且破坏了权重的自然分片，跨模型复用时需重新统计；长度分桶则降低批内填充率，牺牲部分吞吐换尾延迟收敛。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-48\">四十八 · 监控指标体系与回滚判定</h3>\n<p>监控要能区分“精度退化”“性能退化”“稳定性退化”三类，且每类都要有可自动触发的判据。精度侧采集逐 block 相对误差、softmax logits 极值分布、输出 NaN/Inf 计数；性能侧采集单步时延分段占比、reduction 占比、batch 与实际 Tensor Core 利用率；稳定性侧采集校准步标记、rank 间耗时差、显存峰值与碎片率。关键是把这些指标与请求维度关联：分辨率、序列长度、batch、是否命中缓存，否则聚合指标会把尖刺平均掉。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>判据</th><th>处置</th></tr></thead><tbody><tr><td>FID 退化、纹理崩坏</td><td>softmax/残差累加精度</td><td>logits 张量相对误差抬升</td><td>该 block 回退 BF16 累加</td></tr><tr><td>固定位置色块</td><td>per-token scale 被极值主导</td><td>单 token scale 偏离中位数</td><td>改 per-channel 加 outlier 通道</td></tr><tr><td>输出 NaN</td><td>校准间隔过长、scale 漂移</td><td>长序列 logits 溢出计数</td><td>缩短校准间隔、加 clamp</td></tr><tr><td>小 batch 时延反升</td><td>reduction 未融合</td><td>reduction 段占比随 batch 下降上升</td><td>并入 CUDA Graph 与 epilogue</td></tr><tr><td>周期性 P99 尖刺</td><td>校准同步点</td><td>尖刺与校准周期对齐</td><td>校准移出关键路径、异步化</td></tr><tr><td>rank 间等待</td><td>通道切分不均</td><td>rank 耗时最大/中位数比稳定偏高</td><td>按幅值重排切分</td></tr></tbody></table>\n<p>回滚必须是分级的，而不是整体退回 BF16。第一级是算子级回滚：仅把出问题的 block 的 softmax 累加或残差加法切回 BF16，其余 GEMM 保持 FP8，代价是局部 Tensor Core 利用率下降但保住大部分时延收益。第二级是张量级回滚：把该 block 的激活量化从 per-token 改为 per-channel 并保留 outlier 通道，代价是 reduction 结构变化、需要重新校准。第三级是路径级回滚：整条 FP8 路径退回 BF16，仅在精度判据连续越界且前两级无效时触发。回滚触发应绑定具体判据而非人工判断，例如 NaN 计数在滑动窗口内超过阈值即自动降级该 block，并在降级后继续监控以决定是否恢复。</p>\n<p>工程判断上，FP8 在 DiT 上的稳定性边界由 softmax 数值范围与 reduction 开销共同划定：前者决定哪些 block 必须保留 BF16 通道，后者决定 batch 下限。把这两条边界写进部署配置——每个 block 的精度档位与最小 batch——比事后调参更可靠；校准间隔则应作为与序列长度联动的参数，序列越长间隔越短，用校准频率换数值稳定，代价是校准步的周期性尖刺更密，需要靠异步化把它移出关键路径。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-49\">四十九 · FP8 注意力链路的失效边界与可回滚诊断</h3>\n<p>这套方案真正的边界不在峰值吞吐，而在三处数值与调度的接缝：softmax 的指数放大、per-token scale 的 reduction 开销、以及校准节奏与序列长度失配。E4M3 的尾数位宽决定了量化的相对误差量级，校准样本数 N<sub>calib</sub> 只按平方根收敛，$$\\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}}$$ 意味着把校准步数翻四倍才换来误差减半，而长序列注意力中 Q·K<sup>T</sup> 的 logits 动态范围随序列增长而扩张，一旦 activation scale 漂移，softmax 输入被 clamp 截断，注意力图先出现局部塌陷、随后整图崩坏，表现为 FID 明显退化而非直接报错——这是最危险的一类失效，因为它不触发异常，只悄悄掉点。诊断上必须把每层 QKV 输出的 per-channel 最大值、softmax 前的 logits 方差、以及反量化后残差支路的相对误差做成三条常驻指标；残差与 LayerNorm 保留 BF16 是硬约束，任何为省显存把残差也降到 FP8 的改动都应视为越界。</p>\n<p>第二类失效是 OOM 与批抖动耦合。权重与激活显存减半后，容量规划容易按“显存够就加 batch”线性外推，但 DiT 单步前向的中间激活缓存（QKV、注意力矩阵、FFN 中间层）随 batch 与 latent 分辨率同时增长，而 FP8 只压缩了存储位宽、没有压缩注意力矩阵本身的元素数量。单步时延由下式给出上界：$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$ 在小 batch 区间，$M_{\\text{attn}}/\\text{BW}_{\\text{HBM}}$ 项不占主导，反而是 per-token 动态 scale 的 reduction kernel 与 kernel launch 调度成本吃掉收益；批大小在 1–8 之间跳动时，单图时延会出现明显抖动，SLO 以单图时延计时，抖动直接转化为尾延迟尖刺。工程判断是：小 batch 必须把量化 reduction 与 GEMM 一起纳入 CUDA Graph 捕获，否则 FP8 的 30%–45% 单步时延收益会被调度开销部分抵消；同时按“显存水位 + 单步时延”双阈值做准入，而不是只看显存。</p>\n<p>第三类是路由不均与尾延迟。张量并行下若按层切分 QKV 与 FFN，各 rank 的激活 outlier 通道分布不同，per-channel scale 的动态范围不一致，导致部分 rank 的 FP8 GEMM 实际有效吞吐低于均值，形成木桶效应；注意力头若按头切分，个别头的 logits 方差显著偏大，会拖慢整个 all-reduce 的同步点。监控应采集每 rank 的 GEMM 占用率、scale 分布直方图与 all-reduce 等待时间，把“最慢 rank 的 step 时间 / 平均 step 时间”作为路由健康度指标。回滚策略要分级而非一刀切：一级回滚只把注意力矩阵乘（Q·K<sup>T</sup> 与 softmax·V）切回 BF16 累加路径，保留 QKV/FFN 的 FP8 GEMM，代价是损失部分时延收益但保住画质；二级回滚把 FFN 也切回 BF16；三级回滚整体退回 BF16 基线。触发条件绑定具体信号——出现 NaN、色块、或 FID 在线评估越界即触发一级，连续多个校准周期 scale 漂移超阈值则触发二级。校准间隔本身要作为可调参数暴露给运维，长序列与高分辨率场景下缩短间隔、保留更多 BF16 通道，是这套方案规模上限的直接约束。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>softmax/残差量化误差累积</td><td>logits 方差异常、FID 在线退化、注意力图塌陷</td><td>注意力矩阵乘切回 BF16 累加</td></tr><tr><td>scale 漂移致长序列溢出</td><td>输出 NaN、色块、per-channel 最大值越界</td><td>缩短校准间隔并降级 FFN 精度</td></tr><tr><td>reduction 未融合致小 batch 抖动</td><td>单图时延 P99 尖刺、kernel launch 占比升高</td><td>纳入 CUDA Graph 或提升批下限</td></tr><tr><td>张量并行路由不均</td><td>最慢 rank step 时间偏离均值</td><td>重排头/层切分或局部回退 BF16</td></tr></tbody></table>\n<h3 id=\"alg-fp8-dit-attn-sec-50\">五十 · 对照轴：精度档位与实现复杂度</h3>\n<p>把 DiT FP8 注意力与 GEMM 放进同族算法的坐标系，第一条轴不是“快多少”，而是“精度档位—实现复杂度”的二维位置。同族里 BF16 基线处在精度上界、复杂度下界；NVFP4 混合精度处在吞吐上界、精度与调优成本双高的一端；FP8 落在中间偏精度侧。判断依据是 E4M3 承载权重与激活、E5M2 承载梯度类敏感张量这一格式分工，加上残差与 LayerNorm 保留 BF16 的混合结构——它把“降精度”限制在 QKV/FFN GEMM 与注意力矩阵乘两类算子上，其余路径不动。相比之下 NVFP4 混合精度要把更细的块级缩放与敏感层豁免一并设计，kernel 调优资源不足时落地风险显著更高。工程含义是：若团队只有能力维护一套量化路径、又必须守住画质，FP8 是默认档；若已有成熟的块级缩放校准流水线与专门的 kernel 团队，才考虑往 FP4 侧迁移。代价侧要记住 FP8 的吞吐只有 FP4 的一半，这一条直接决定容量规划里单卡能扛多少并发 latent。</p>\n<div class=\"formula\">$$\\text{FLOPs}_{\\text{eff}} = \\frac{\\text{FLOPs}_{\\text{bf16}}}{2},\\quad \\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}}$$</div>\n<p>上式给出两个可对照的量：有效算力减半对应 BF16 的两倍吞吐关系，而量化误差随校准样本数 $N_{\\text{calib}}$ 以平方根收敛。它解释了为什么 FP8 与 NVFP4 的差距不只是格式位宽，还包括校准投入——把 $N_{\\text{calib}}$ 压小去省离线成本，误差项立刻抬头，画质敏感场景下这笔账算不过来。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-51\">五十一 · 决策表：按负载形态选档</h3>\n<p>第二条轴是负载形态。DiT 单步前向的批量 latent 生成，批大小按显存与 SLO 取 1–8，SLO 以单图时延计——这个区间决定了 reduction 开销的相对权重。小 batch 下 per-token 动态 scale 的 reduction kernel 占比上升，必须与 CUDA Graph 融合才能摊薄调度成本；大 batch 或高分辨率 latent 下 reduction 被摊薄，FP8 的收益才充分释放。因此选档不能只看“画质要求”，还要看服务实际跑在哪个 batch 区间。</p>\n<table class=\"mini\">\n<thead><tr><th>场景条件</th><th>推荐档位</th><th>关键理由</th><th>主要代价</th></tr></thead>\n<tbody>\n<tr><td>注意力与 FFN GEMM 占主导、显存受限的服务化部署</td><td>FP8（E4M3 权重/激活 + E5M2 敏感张量）</td><td>权重与激活显存减半，可容纳更大 batch 或更高分辨率 latent；单步时延降 30%–45%</td><td>softmax 与残差需保留 BF16 累加与 outlier 通道</td></tr>\n<tr><td>画质极敏感、kernel 调优资源有限</td><td>FP8 优先于 NVFP4</td><td>精度更高、实现更简单，无需块级缩放全套流水线</td><td>吞吐只有 FP4 的一半</td></tr>\n<tr><td>已有块级缩放校准与专用 kernel 团队、吞吐为第一目标</td><td>NVFP4 混合精度</td><td>吞吐上界更高</td><td>校准与豁免设计复杂，掉点风险需专门兜底</td></tr>\n<tr><td>batch 长期处于 1–2 的小区间</td><td>FP8 + CUDA Graph 融合，或退回 BF16</td><td>reduction 开销在小 batch 下吃掉收益</td><td>融合不到位则单步时延不降反升</td></tr>\n<tr><td>超长序列、高分辨率 latent</td><td>FP8 但扩大 BF16 保留通道</td><td>softmax 数值稳定性与 reduction 开销构成规模上限</td><td>保留通道增多，显存与带宽收益缩水</td></tr>\n<tr><td>无量化基础设施、仅求稳定上线</td><td>BF16 基线</td><td>零校准风险</td><td>显存占用高、单步时延难压</td></tr>\n</tbody>\n</table>\n<p>表的读法是逐行排除：先看 batch 区间是否落在 reduction 敏感区，再看画质容差，最后看团队是否具备块级缩放能力。三问之后通常只剩一个候选档，避免“全都想要”的配置蔓延。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-52\">五十二 · 与 BF16 基线的分界条件</h3>\n<p>FP8 相对 BF16 的收益不是无条件成立，分界线在时间预算的构成上。单步时延近似为显存搬运与 Tensor Core 计算两条路径的较大者：</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</div>\n<p>若当前步已被 HBM 带宽项主导（$M_{\\text{attn}}$ 指注意力相关中间激活与 KV 的搬运量），换 FP8 把权重与激活显存减半，等于直接压低带宽项，收益立现；若步时被 Tensor Core 项主导，则要看 FP8 吞吐约为 BF16 两倍这一条能否把计算项压到带宽项之下，一旦压过去，继续加精度档位（往 FP4 走）对单步时延的边际贡献就变小，因为瓶颈已换到搬运侧。这就是“先判断瓶颈项、再选精度档”的工程顺序，而不是先选档再测。具体例子：一个以 QKV/FFN GEMM 为主的中等分辨率服务，batch 取 4–8 时计算项占优，FP8 把计算项减半后步时下降明显；同一模型把 batch 压到 1，reduction 与调度开销抬头，收益被侵蚀，此时应先把 per-token scale 的 reduction 融进 CUDA Graph，再谈是否值得保留 FP8。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-53\">五十三 · 与 NVFP4 混合精度的取舍边界</h3>\n<p>FP8 与 NVFP4 的分界不在“谁更先进”，而在误差预算与调优预算的交换率。FP8 的误差项由 $\\Delta_{\\text{fp8}}/\\sqrt{N_{\\text{calib}}}$ 控制，靠每 N 步校准一次 activation scale 写回缓存来抑制漂移；NVFP4 要把同样的误差压到可接受区间，需要更密的缩放粒度与更细的敏感层豁免，校准流水线与 kernel 复杂度同步上升。因此判断规则可以写成：当画质容差紧、且团队无法长期维护块级缩放校准与专用 kernel 时，选 FP8；当吞吐是硬约束、且已有校准基础设施可复用，才把 NVFP4 纳入候选。注意 FP8 的吞吐只有 FP4 的一半这一事实必须进入容量规划——同样的 SLO 下，FP4 路线单卡可承载的并发更高，但一旦掉点需要回退，回退成本也更高（要重建校准与豁免表）。工程上更稳的做法是把 FP8 作为默认档并把 NVFP4 作为可开关的实验档，用同一套 SLO 压测对比，而不是在架构期就锁死。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-54\">五十四 · 与异步注意力及缓存类算法的耦合选择</h3>\n<p>同族里还有一类不改变数值精度、只改变执行编排的算法：Blackwell 异步 FA3 注意力、特征缓存与块级跳步、CFG 批合并与条件缓存。它们与 FP8 的关系是正交而非替代——FP8 降的是单算子成本，编排类算法降的是调用次数与空转。选型时要防止收益重叠被误算成叠加：若特征缓存已把部分 block 跳过，被跳过的 GEMM 本就不执行，FP8 对这部分没有额外收益，此时 FP8 的价值集中在剩余未跳过的 QKV/FFN 与注意力矩阵乘上，收益比例会低于 30%–45% 的整步口径。反过来，若 CFG 批合并把条件与非条件两条流合成一个 batch，FP8 的显存减半收益被放大——合并后的 batch 更容易撞上显存上限，减半正好腾出空间。判断规则：先确认编排类算法已把无效计算削掉，再评估 FP8 在剩余计算上的占比；占比低于主导阈值时，优先做编排优化而非继续压精度。代价侧提醒：异步注意力与 FP8 同用时，softmax 内部 BF16 累加与 FP8 矩阵乘的流水交界处是数值风险点，需在长序列下专门验证溢出。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-55\">五十五 · 适用条件与规模上限的工程判断</h3>\n<p>FP8 的适用边界由两条约束夹出：softmax 数值稳定性与 reduction 开销。前者决定超长序列与高分辨率 latent 下必须保留更多 BF16 通道，保留通道越多，显存与带宽收益越缩水，形成规模上限；后者决定小 batch 区间必须靠 CUDA Graph 融合摊薄调度成本，否则 FP8 收益被 reduction kernel 吃掉。校准间隔是第三条隐性约束：间隔过长会让 activation scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块——这类失败不是精度档位选错，而是校准策略与序列长度不匹配。工程判断可以落成三条检查：其一，确认目标 batch 区间内 reduction 已融合且实测步时确实下降；其二，确认 softmax 与残差路径保留 BF16 累加与 outlier 通道，并用长序列压测验证无溢出；其三，把校准间隔与序列长度、分辨率绑定成配置项而非全局常数，随负载形态调整。三条都过，FP8 才是该服务的正确档位；任一条不过，应退回 BF16 或先做编排类优化，而不是靠调低校准样本数去换吞吐——那会把误差项直接推到画质侧。</p>\n\n<h3 id=\"alg-fp8-dit-attn-sec-56\">五十六 · 同族对照：BF16、FP8 与 NVFP4 之间的选型判据</h3>\n<p>把 DiT 的 QKV/FFN GEMM 与注意力矩阵乘降精度，可选路径并非只有一条。BF16 基线保留全部数值余量，代价是 Tensor Core 吞吐与显存带宽都停在原位；FP8（E4M3 承载权重与激活、E5M2 承载敏感张量）把这两类算子统一降精度，换来约 2 倍的 Tensor Core 吞吐与权重/激活显存减半；NVFP4 混合精度再进一步，吞吐约为 FP8 的两倍，但精度余量更薄、实现复杂度更高。选型的核心不是“谁最快”，而是判断当前负载的瓶颈落在哪一侧：若单步时延被 Tensor Core 吞吐钉住且画质容错尚可，FP8 是性价比拐点；若显存是硬约束、batch 与 latent 分辨率被迫压缩，FP8 的显存减半直接转化为可服务的 batch 上限；若画质指标（FID 类）是硬 SLO 且 kernel 调优人力有限，BF16 或 FP8 加更多 BF16 通道比激进上 FP4 更稳。判据可写成一条粗略的收益不等式：只有当 <span class=\"formula\">$$\\text{FLOPs}_{\\text{eff}} = \\frac{\\text{FLOPs}_{\\text{bf16}}}{2}$$</span> 带来的时延压缩大于量化引入的返工与调优成本时，降精度才划算——FP8 恰好落在这条线的常用区间内，而 FP4 需要额外的 outlier 处理与更密的校准才能守住画质。</p>\n<p>失效条件要按机制逐条对照，而不是笼统地说“精度不够”。第一类是 softmax 与残差路径：这两处对量化误差敏感，若未保留 BF16 累加与 outlier 通道，误差会沿注意力图累积，表现为 FID 明显退化与注意力图崩坏；FP8 方案对此的防护是 softmax 内部 BF16 累加、残差与 LayerNorm 留在 BF16，NVFP4 则需要更宽的补偿通道。第二类是 reduction 开销：per-token 动态 scale 引入额外 reduction kernel，小 batch（1–8）下其占比上升，若未与 CUDA Graph 融合，调度开销会吃掉 FP8 收益，此时 FP8 相对 BF16 的净时延优势可能被抹平，而 NVFP4 因量化步骤更多、更依赖融合，风险更高。第三类是校准漂移：校准间隔过长会让 activation scale 漂移，长序列注意力出现数值溢出，输出 NaN 或色块；校准误差随样本数收敛的定性关系是 <span class=\"formula\">$$\\Delta_{\\text{err}} \\approx \\frac{\\Delta_{\\text{fp8}}}{\\sqrt{N_{\\text{calib}}}}$$</span>，即校准样本翻四倍才能把误差减半，这决定了“每 N 步校准一次”的 N 不能随意放大。第四类是规模上限：超长序列与高分辨率 latent 下需保留更多 BF16 通道，FP8 的有效加速比随之收窄，此时 FP4 的吞吐优势更难兑现。</p>\n<p>系统代价要按单步时延的组成来估：<span class=\"formula\">$$T_{\\text{step}} \\approx \\max\\left(\\frac{M_{\\text{attn}}}{\\text{BW}_{\\text{HBM}}}, \\frac{\\text{FLOPs}}{\\text{TC}_{\\text{fp8}}}\\right)$$</span>。这条式子说明选型要看 max 的哪一项占优：显存受限、注意力中间张量搬运量大的部署，降精度减半显存与带宽需求直接压第一项；算力受限、GEMM 占主导的部署，FP8 的 2 倍吞吐压第二项，实测单步时延可降 30%–45%。NVFP4 把第二项再压一半，但第一项受益有限，且量化/反量化与 outlier 处理会新增 kernel 与同步点，在小 batch 下反而抬高固定开销。工程判断因此可以落成一张决策表：画质敏感或调优资源有限选 FP8；显存与吞吐双紧、且已有成熟 FP4 量化流水线才考虑 NVFP4；对数值稳定性零容忍、或序列长度与分辨率超出 FP8 稳定区间时退回 BF16 并把优化预算放在调度与并行上。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>吞吐/显存</th><th>主要失效条件</th><th>适用场景</th></tr></thead><tbody><tr><td>BF16 基线</td><td>基准；显存最高</td><td>无量化误差，但时延与 batch 上限受吞吐/显存钉住</td><td>画质硬 SLO、超长序列、调优预算不足</td></tr><tr><td>FP8（E4M3+E5M2）</td><td>吞吐约 2×，权重与激活显存减半</td><td>softmax/残差未留 BF16 累加；reduction 未融合；校准间隔过长致溢出</td><td>GEMM 占主导、显存受限的服务化部署，单步时延可降 30%–45%</td></tr><tr><td>NVFP4 混合</td><td>吞吐约为 FP8 的 2×，显存更省</td><td>精度余量薄，需更密校准与 outlier 通道，实现复杂度高</td><td>吞吐/显存双紧且已有成熟 FP4 流水线与调优人力</td></tr></tbody></table>\n<p>落到具体例子：一个以单图时延为 SLO、batch 取 1–8 的 DiT 服务，若 profiling 显示 QKV 与 FFN GEMM 占据单步大头、且显存刚好卡住 batch 上限，FP8 是首选——它把两类 GEMM 与注意力矩阵乘统一降精度，残差与 LayerNorm 留 BF16，配合每 N 步校准与 CUDA Graph 融合 reduction，既拿到吞吐又守住画质；反之，若瓶颈在 VAE 解码或调度排队、GEMM 并非主导，降精度收益会被非 GEMM 段稀释，此时应先做批调度与分离式预填/解码，而不是把预算压在 FP4 上。选型的最终判据是：先量化单步时延中 GEMM 与注意力搬运的占比，再对照上表的失效条件逐条排查，只有当 FP8 的三类失效条件都被机制性防住（BF16 累加、融合 reduction、受控校准间隔）时，才把 NVFP4 列为下一档候选。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · VAE 解码与潜空间压缩</td></tr><tr><td>解决什么</td><td>Blackwell 上 DiT 的 QKV 投影与注意力 GEMM 受 FP16 带宽与 Tensor Core 吞吐…</td></tr><tr><td>一句话机制</td><td>用 E4M3 承载权重与激活、E5M2 承载梯度类敏感张量，配合 per-tensor/per-channel sca…</td></tr><tr><td>代价与失效</td><td>注意力 softmax 与残差对量化误差敏感，需保留 BF16 累加与 outlier 通道，否则 FID 明显退化；per-token …</td></tr><tr><td>后继</td><td>特征缓存与块级跳步</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-fp8-dit-attn · 共 8 个片段</p>\n";break;}}})();
